"Ab 20 Minuten Spielzeit kannst du dem Entwickler eine Rückmeldung geben. Verschickt wird sie nur, wenn du selbst auf „Per E-Mail senden“ klickst (öffnet dein Mailprogramm) oder den Text für Discord kopierst und abschickst. Was du ins Formular schreibst, auch das freiwillige Kontaktfeld, wird nicht gespeichert.":"После 20 минут игры можно отправить отзыв разработчику. Он уйдёт, только если вы сами нажмёте «Отправить по e-mail» (откроется почтовая программа) или скопируете текст для Discord и отправите его. То, что вы пишете в форме, включая необязательное поле контакта, не сохраняется.",
