"Ab jetzt sollte man zusammen spielen können, und zwar ohne teuren Spielserver: Die Browser der Spieler verbinden sich direkt miteinander, ein Raumcode reicht. Bis zu 32 Spieler, Bots füllen auf, und ein Anti-Cheat prüft die Treffer. Weil ich mir gerade eine VR-Brille geholt hatte, kam auch noch ein VR-Modus für die Meta Quest 3 dazu.":"Отныне можно было играть вместе, причём без дорогого игрового сервера: браузеры игроков соединяются напрямую, достаточно кода комнаты. До 32 игроков, боты добирают состав, а античит проверяет попадания. Поскольку я как раз купил VR-шлем, добавился ещё и VR-режим для Meta Quest 3.",
