"Absprung über einer Großkarte, nur mit dem Messer. Waffen, Munition, Westen, Helme, Verbände und Granaten liegen in Häusern und Stellungen – dazu seltene Waffen, die es nur hier gibt. Die Zone zieht sich in mehreren Phasen zusammen, außerhalb kostet jede Sekunde Leben. Kein Wiedereinstieg: Wer als Letzter steht, gewinnt.":"Прыжок над большой картой — только с ножом. Оружие, патроны, бронежилеты, шлемы, бинты и гранаты лежат в домах и на позициях, а также редкое оружие, которое есть только здесь. Зона сужается в несколько этапов; за её пределами каждая секунда отнимает здоровье. Без возрождения: побеждает последний выживший.",
