"Alle an Bord? Ich zähle vierzehn Zivilisten und euch drei. Libelle 1 hebt ab.":"Все на борту? Считаю четырнадцать гражданских и вас троих. «Либелле 1» взлетает.",
"Alle brauchen dieselbe Spielfassung. Die PC-App sagt Bescheid, wenn die Webseite neuer ist.":"У всех должна быть одна версия игры. Приложение для ПК сообщит, если сайт новее.",
"Alle drei markiert. Die Pioniere warten auf euer Zeichen. Jetzt der Kapitän.":"Все три помечены. Сапёры ждут вашего сигнала. Теперь капитан.",
"Alle drei sind weg. Aber der mit dem Funkgerät hat noch gesendet, bevor Lenz ihn hatte. Zwei Worte: „Jetzt sofort“.":"Все трое убраны. Но тот, что с рацией, успел передать, пока Ленц его не взял. Два слова: «Прямо сейчас».",
"Alle raus, ausschwärmen! Falke, nimm den Donnerkeil aus dem Gestell – den brauchen wir noch.":"Все наружу, рассредоточиться! Фальке, возьми «Доннеркайль» со стойки – он ещё понадобится.",
"Alle raus. Keiner zurückgelassen.":"Все вышли. Никого не оставили.",
"Alle sechs Einsätze":"Все шесть заданий",
"Alle seltenen Muster dieser Waffe:":"Все редкие узоры этого оружия:",
"Alle tragen nur das Messer":"У всех только нож",
"Alle verfügbaren Missionen erledigt – weitere folgen mit kommenden Updates.":"Все доступные миссии пройдены – новые появятся с обновлениями.",
"Alle {0} Mitspieler werden":"Все {0} товарищей будут",
"Alle Überlebenden gefallen":"Все выжившие пали",
"Allein am Stand":"Один на стрельбище",
"Allein am Stand. Unbegrenzte Munition, jede Waffe frei wählbar, Bestzeiten im Parcours.":"Один на стрельбище. Бесконечные патроны, любое оружие, рекорды на полосе.",
"Allein gegen die Untoten. Fällst du, ist es vorbei.":"Один против нежити. Падёте – всё кончено.",
"Allein im Trupp: du bleibst Truppführer.":"Вы один в отделении: остаётесь командиром.",
"Allein, ohne Gegner, ohne Zeitdruck.":"Один, без противников, без спешки.",
"Allen geht es gut. Ein Kind hat nach dir gefragt – ob du der Soldat bist, der die Glocke wieder läuten lässt.":"Со всеми всё в порядке. Один ребёнок спрашивал про тебя – ты ли тот солдат, который снова заставит колокол звонить.",
"Alles":"Всё",
"Alles im Blick: Minikarte, Kompass, Munition, Leben, Treffermarker.":"Всё на виду: миникарта, компас, патроны, здоровье, маркеры попаданий.",
"Alles selbst: Magazine, Durchladen, Sicherung, Ladehemmungen, Visier, Verwundungen, Gewicht – kein HUD, kein Fadenkreuz.":"Всё сами: магазины, затвор, предохранитель, задержки, прицел, ранения, вес – без интерфейса и прицела.",
"Alles selbst: Magazine, Durchladen, Sicherung, Verwundungen, kein HUD – Gegner wie Veteran, 5 Wiedereinstiege.":"Всё сами: магазины, затвор, предохранитель, ранения, без интерфейса – враги как на «Ветеране», 5 возрождений.",
"Alles zurücksetzen":"Сбросить всё",
"Alles, was NULLPUNKT ausmacht, stammt von mir:":"Всё, что составляет NULLPUNKT, придумал я:",
"Allrounder":"Универсал",
"Allrounder für mittlere Distanz – verlässlich, vielseitig, kontrollierbar.":"Универсал для средней дистанции – надёжный, гибкий, управляемый.",
