"Als erster Infizierter drei Überlebende erwischt.":"Будучи первым заражённым, достали трёх выживших.",
"Alt + Eingabe":"Alt + Enter",
"Altbauten mit Läden und Wohnungen, Hinterhöfe, Straßenbahn, U-Bahn und Dächer.":"Старые дома с магазинами и квартирами, дворы, трамвай, метро и крыши.",
"Alte Frontstellung Süd":"Старая фронтовая позиция «Юг»",
"Altstadt":"Старый город",
"Altstadt in umgekehrter Richtung (Osten → Westen)":"Старый город в обратном направлении (восток → запад)",
"Altstadt: Bresche in einer Hauswand nach Dauerfeuer und einer Rakete, mit Staub und Trümmern.":"Старый город: пролом в стене дома после шквального огня и ракеты, с пылью и обломками.",
"Am Eingang bereit!":"Готовы у входа!",
"Am Fallschirm – mit der Laufrichtung steuern":"На парашюте — управляй клавишами движения",
"Am Nordkai liegt der Frachter „Seeschwalbe“ mit Kessars gefälschten Uniformen und Sprengstoff. Schleich dich mit Weber über das Terminal, markiere die Container und hol den erpressten Kapitän heraus – ohne Alarm.":"У Северного причала стоит сухогруз «Зеешвальбе» с поддельной формой и взрывчаткой Кессара. Проберитесь с Вебером через терминал, пометьте контейнеры и вытащите шантажируемого капитана – без тревоги.",
"Am Schießstand Hohenfeld lernst du unter Oberfeldwebel Krell alles, was die Kampagne verlangt: Bewegung, Waffen, Granaten, Ausrüstung, Befehle an den Trupp und den Geländewagen. Jeder Schritt wartet auf dich.":"На стрельбище Хоэнфельд прапорщик Крелль научит всему, что потребуется в кампании: движение, оружие, гранаты, снаряжение, приказы отделению и внедорожник. Каждый шаг ждёт вас.",
"Am Vorderschaft: Gewehr beidhändig führen (einhändig streut es stark). An der Brust: Granate nehmen, Abzug zieht den Splint, Loslassen wirft.":"На цевье: держать винтовку двумя руками (одной – сильный разброс). На груди: взять гранату, спуск выдёргивает чеку, отпустил – бросил.",
"Am Wochenende":"На выходных",
"Am selben Abend":"Тем же вечером",
"Amboss":"«Наковальня»",
"Amboss (Kompanie)":"«Наковальня» (рота)",
"Amboss an Falke 2 und Kiesel: Die Korvaner halten die Brücken von Mirenfurt. Wir nehmen die Stadt zurück – Haus für Haus.":"«Наковальня» «Соколу-2» и «Гальке»: корванцы удерживают мосты Миренфурта. Возвращаем город – дом за домом.",
"Amboss an Falke 2: Ihr habt Feuerfreiheit ab der Sperrlinie. Viel Glück.":"«Наковальня» «Соколу-2»: от заградительной линии огонь разрешён. Удачи.",
"Amboss an Falken: Aufklärung meldet zwanzig Fahrzeuge im Anmarsch auf die Höhe. Die Kompanie braucht noch eine halbe Stunde.":"«Наковальня» «Соколам»: разведка докладывает о двадцати машинах, идущих на высоту. Роте нужно ещё полчаса.",
"Amboss an alle Falken: Auftrag erfüllt. Sammeln am Markt. Ende.":"«Наковальня» всем «Соколам»: задача выполнена. Сбор у рынка. Конец связи.",
"Amboss an alle Falken: Korvanische Panzer haben um vier Uhr die Grenze bei Mirenfurt überschritten. Vor uns liegt ihre Sperrlinie.":"«Наковальня» всем «Соколам»: в четыре часа корванские танки перешли границу у Миренфурта. Перед нами их заградительная линия.",
"Amboss: Die Kompanie ist auf der Höhe. Der Feind zieht sich zurück.":"«Наковальня»: рота на высоте. Противник отходит.",
"Amboss: Funkstelle ist still. Gut gemacht, Graufalken. Die Artillerie schießt jetzt ins Leere.":"«Наковальня»: радиоточка молчит. Отлично, «Серые соколы». Их артиллерия теперь бьёт вслепую.",
"Amboss: Lager und Brücke brennen. Der Hauptverband steht ohne Treibstoff.":"«Наковальня»: лагерь и мост горят. Главные силы остались без топлива.",
"An":"Вкл.",
"An (35 %)":"Вкл. (35 %)",
"An (auch dein Fahrzeug)":"Вкл. (и техника тоже)",
"An den Körper ziehen":"Прижать к телу",
"An der Furt stand ihr schwerer Moloch. Von vorn prallte alles an ihm ab. Emil wusste das.":"У брода стоял их тяжёлый «Moloch». В лоб от него всё отскакивало. Эмиль это знал.",
"An euch alle ein riesiges Dankeschön! Als Geschenk bekommt jeder, der bis zum 13. Oktober 2026 gespielt hat:":"Огромное спасибо всем вам! В подарок каждый, кто играл до 13 октября 2026 года, получает:",
