"Arcade":"Аркада",
"Arcade zeigt dir alles und heilt schnell. Realistisch blendet Gegner und fast das ganze HUD aus und macht Treffer tödlicher. Simulation geht noch weiter: Magazine, Durchladen, Ladehemmungen, Verwundungen, kein HUD. Der Vergleich steht unter":"Аркада показывает всё и быстро лечит. Реализм скрывает врагов и почти весь HUD и делает попадания смертоноснее. Симуляция идёт дальше: магазины, досылание, задержки, ранения, без HUD. Сравнение – в разделе",
"Arcade – {0}":"Аркада – {0}",
"Arcade, Realistisch, Simulation vergleichen":"Сравнить: аркада, реализм, симуляция",
"Arcade: Du fährst und schießt allein (Rolle gilt nur in der Simulation).":"Аркада: ты ведёшь и стреляешь сам (роль действует только в симуляции).",
"Arcade: W/A/S/D fahren, Maus richten, Linksklick Feuer, 1–4 Munition.":"Аркада: W/A/S/D – движение, мышь – наводка, ЛКМ – огонь, 1–4 – боеприпасы.",
"Arcade: das bekannte Spiel. Realistisch: keine Gegneranzeigen, minimales HUD, mehr Schaden, langsamere Heilung.":"Аркада: привычная игра. Реализм: без меток врагов, минимум интерфейса, больше урона, медленнее лечение.",
"Arcade: du fährst und schießt; Platzwechsel Richtschütze ↔ Fahrer ↔ Kommandant mit dem Sitzrad (K halten).":"Аркада: вы ведёте и стреляете; смена места наводчик ↔ водитель ↔ командир колесом мест (удерживать K).",
"Archiv":"Архив",
