"Archivar Kemper":"Архивист Кемпер",
"Archivarin Sell":"Архивистка Зелль",
"Arm verletzt":"Рука ранена",
"Armbrust mit Umlenkrollen und Spannhilfe: Ein Bolzen, kein Knall, kein Mündungsfeuer. Der Bolzen fliegt sichtbar im Bogen – wer den Fall einrechnet, trifft lautlos bis weit über fünfzig Meter, ein Kopftreffer genügt immer.":"Блочный арбалет со взводным устройством: один болт, ни грохота, ни вспышки. Болт летит по заметной дуге — если учесть снижение, бьёшь бесшумно дальше пятидесяти метров, а попадания в голову хватает всегда.",
"Armbrustbolzen":"Арбалетные болты",
"Arsenal":"Арсенал",
"Arterienblutung an Arm oder Bein: In einer halben Minute bist du bewusstlos. Abbinden stoppt sie sofort – das Glied bleibt danach beeinträchtigt.":"Артериальное кровотечение на руке или ноге: через полминуты вы без сознания. Жгут сразу останавливает его – но конечность потом работает хуже.",
