"Auf den meisten aktuellen Handys ja, auf der Grafikstufe „Niedrig“ oder „Mittel“. Das Handy quer halten. Nötig ist ein Browser mit WebGL 2. Die Übersicht steht unter":"На большинстве современных телефонов да, на графике «Низкая» или «Средняя». Держите телефон горизонтально. Нужен браузер с WebGL 2. Обзор – в разделе",
"Auf der rechten Hälfte ziehen. Optional Gyro (Einstellungen → Steuerung).":"Тяните по правой половине. Гироскоп по желанию (Настройки → Управление).",
"Auf eine Meile":"За милю",
"Auf fünfzig Meter und weiter: hinlegen, anlegen, ruhig atmen.":"На пятьдесят метров и дальше: лечь, прицелиться, спокойно дышать.",
"Auf vielen echten Grafikkarten war plötzlich der Boden unsichtbar. Der Grund: Der Gelände-Shader brauchte 17 Texturen, dort sind aber nur 16 erlaubt. In der Testumgebung fiel das nicht auf, weil sie 32 erlaubt. Der Hotfix kam noch am selben Abend. In den Tagen davor waren neue Ego-Hände und neue Körper für die Soldaten entstanden. Danach Akt III der Kampagne mit den Missionen 12 bis 15 und die Panzersimulation: vier Plätze, jeder Handgriff selbst, mit Tutorial, Hilfe oder ganz frei.":"На многих реальных видеокартах земля вдруг стала невидимой. Причина: шейдеру рельефа требовалось 17 текстур, а там разрешено только 16. В тестовой среде этого не заметили, потому что она разрешает 32. Исправление вышло в тот же вечер. В предыдущие дни появились новые руки от первого лица и новые тела солдат. Затем – третий акт кампании с миссиями с 12 по 15 и танковая симуляция: четыре места, каждое действие сам, с обучением, подсказками или полностью свободно.",
