"Bei Verstößen behalte ich mir rechtliche Schritte vor, insbesondere Unterlassung, Beseitigung und Schadensersatz. Es gilt deutsches Recht. Anfragen und Genehmigungen: Discord":"При нарушениях оставляю за собой право на судебные меры, в частности требования о прекращении, устранении и возмещении ущерба. Применяется право Германии. Запросы и разрешения: Discord",
