"Beide unten! Seyfried ist allein. Abschießen dürfen wir ihn nicht – wir brauchen ihn. Zwing ihn runter: dichte Überflüge, damit sein Pilot begreift, dass er keine Wahl hat.":"Оба сбиты! Зайфрид один. Сбивать его нельзя – он нам нужен. Прижми его к земле: проходы вплотную, чтобы его пилот понял, что выбора нет.",
