"Da oben – der Gittermast und der Bunker. Fünf Mann, vielleicht mehr im Bunker. Die Sendung beginnt in zehn Minuten.":"Наверху – решётчатая мачта и бункер. Пятеро, может, больше внутри. Передача начнётся через десять минут.",
