"Echter Körper":"Настоящее тело",
"Echtes Bild im Zielfernrohr":"Реальное изображение в оптике",
"Echtes Ducken, Hinlegen und Lehnen (Kopfbewegung)":"Реальное приседание, залегание и наклон (движением головы)",
