"Ego-Shooter im Browser. Gegen Bots oder online mit Freunden. Kein Download, kein Konto.":"Шутер от первого лица в браузере. Против ботов или онлайн с друзьями. Без скачивания и аккаунта.",
"Ego-Sicht":"Вид от первого лица",
"Eher nicht: nur ich und eine KI.":"Не совсем: только я и ИИ.",
"Ehrlich gesagt":"Честно говоря",
"Eigene Belegung? Im Spiel unter Einstellungen → Steuerung. Was du dort änderst, steht hier.":"Своя раскладка? В игре: Настройки → Управление. Что изменишь там, появится здесь.",
"Eigene Einstellung – eine Vorlage stellt alle Werte darunter auf einmal.":"Свои настройки – шаблон задаёт все значения ниже разом.",
