"Eingegrabene Pak, ein Bunker an der Straße und dahinter eine Funkstelle, die ihre Artillerie lenkt. Ohne die Funkstelle sind sie blind.":"Окопанные ПТО, дот у дороги, а за ним радиоточка, которая наводит их артиллерию. Без неё они слепы.",
