"Einschusslöcher je Kaliber, Querschläger und Durchschüsse. Dauerfeuer frisst sich durch Wände, Sprengungen reißen begehbare Breschen mit gebrochenen Rändern, Ruß und Staub. Türen fallen aus zerschossenen Scharnieren, Bäume kippen, Panzer schieben Gebäude ein.":"Пробоины по калибру, рикошеты и сквозные попадания. Длинные очереди прошивают стены, взрывы пробивают проходимые бреши с рваными краями, сажей и пылью. Двери слетают с простреленных петель, деревья падают, танки сносят здания.",
"Einschüssiger 40-mm-Granatwerfer: Splittergranate im hohen Bogen, scharf ab 12 m. Räumt Fenster, Gräben und Stellungen.":"Однозарядный 40-мм гранатомёт: осколочная граната по высокой траектории, взводится с 12 м. Зачищает окна, окопы и позиции.",
"Einsteigen":"Сесть",
