"Einsteigen: F · Gamepad X · Touch: Knopf „Einsteigen“. Wachen an der Bahn zuerst ausschalten.":"Сесть: F · геймпад X · сенсор: кнопка «Сесть». Сначала уберите охрану у полосы.",
"Einsteigen: F · Gamepad X · Touch: „Einsteigen“. Der Fahrersitz ist besetzt – du kommst ans MG.":"Сесть: F · геймпад X · сенсор: «Сесть». Место водителя занято – вы за пулемётом.",
