"Erlaubnis, ihn zu verwenden. Es wird keine Lizenz erteilt; Ansehen und Spielen bedeuten keine Übertragung von Rechten.":"даёт разрешения на его использование. Лицензия не предоставляется; просмотр и игра не означают передачи прав.",
"Erlaubt (alle Modi): wer es nutzt, trägt ein Symbol in der Punktetabelle":"Разрешено (все режимы): кто пользуется, получает значок в таблице",
