"Erscheint in Tabelle und Abschussmeldungen.":"Отображается в таблице и ленте убийств.",
"Erscheint neben dir, du sitzt sofort am Steuer (Jets: auf der Startbahn). Das zuvor gerufene verschwindet.":"Появляется рядом, ты сразу за управлением (самолёты – на полосе). Вызванная ранее техника исчезает.",
"Erst VR-Modus einschalten.":"Сначала включите режим VR.",
"Erst anhalten":"Сначала остановись",
"Erst aussteigen.":"Сначала выйдите.",
"Erst das Lager, dann die Brücke. Danach sofort zurück. Ich will euch vor Sonnenaufgang wiedersehen.":"Сначала лагерь, потом мост. Затем сразу назад. Хочу увидеть вас до рассвета.",
"Erst die Kapelle, dann das Gerät. Und jeder Verwundete wird geborgen – gleich, welche Uniform er trägt.":"Сначала часовня, потом рация. И каждого раненого выносим – неважно, в какой он форме.",
