"Erste Fassung – Fehler gerne melden":"Ранняя версия – сообщайте об ошибках",
"Erste Fassungen von Mehrspieler und VR, neue Animationen, Befehlsrad und der Modus „Nur Messer“.":"Первые версии мультиплеера и VR, новые анимации, колесо приказов и режим «Только ножи».",
"Erste Flugabwehr, gleich vor uns. Wachen ausschalten, dann Ladung dran.":"Первая зенитка прямо перед нами. Снять охрану, потом заложить заряд.",
