"Erster Mann: Warnweste, Arbeitsjacke. Er geht an der Ostseite auf und ab und schaut nie zum Podium.":"Первый: светоотражающий жилет, рабочая куртка. Ходит взад-вперёд с восточной стороны и ни разу не смотрит на трибуну.",
"Erster Sieg":"Первая победа",
