"FXAA ist billig, SMAA schärfer und ruhiger. TAA verrechnet mehrere Bilder: feine Details (Zäune, Gras, Kanten) und weiche Schatten stehen ruhig, das Bild wird etwas weicher.":"FXAA дешёвый, SMAA резче и стабильнее. TAA смешивает несколько кадров: мелкие детали (заборы, трава, края) и мягкие тени не мерцают, картинка чуть мягче.",
