"Fahren und schießen zugleich, Automatiklader, Außenansicht.":"Езда и стрельба одновременно, автомат заряжания, внешний вид.",
"Fahrer":"Механик-водитель",
"Fahrer und Infanterie im Transportfahrzeug – schnell an die Front, absitzen, angreifen.":"Водитель и пехота в транспорте – быстро на фронт, спешиться, атаковать.",
"Fahrer – Motor anlassen!":"Механик – заводи мотор!",
"Fahrer-Winkelspiegel":"Перископ механика",
"Fahrer: Motor anlassen, Bremse lösen, Gang einlegen. Fahrbefehle des Kommandanten stehen oben im Bild.":"Механик-водитель: завести мотор, снять с тормоза, включить передачу. Команды командира – вверху экрана.",
"Fahrerplatz: Fahren, Befehle des Kommandanten oben im Bild.":"Место механика: вождение, приказы командира вверху экрана.",
"Fahrerraum":"Отделение управления",
"Fahrersehklappe":"Смотровой люк механика",
