"Fahrstrecke":"Автодром",
"Fahrstrecke mit Slalom, Rampe, Steigungen, Graben, Furt und Bodenwellen":"Трасса со слаломом, рампой, подъёмами, канавой, бродом и неровностями",
"Fahrt vorn, aber nicht zu weit. Die Wagen sind nicht gepanzert. Ohne sie steht morgen die ganze Kompanie still.":"Идите впереди, но не слишком далеко. Машины не бронированы. Без них завтра встанет вся рота.",
