"Falscher Kanal – die Kompanie hört auf Kanal 5":"Не тот канал – рота слушает канал 5",
"Falscher Schritt":"Неверный шаг",
"Falsches Team.":"Не та команда.",
"Familie":"Семья",
"Familie aus der Gasse in den Keller bringen (Begleitschutz)":"Отвести семью из переулка в подвал (сопровождение)",
"Farbe {0} verwenden":"Использовать цвет {0}",
"Farben (2–4)":"Цвета (2–4)",
"Farbstimmung":"Цветокоррекция",
"Fassung des Zwiegesprächs":"Версия диалога",
"Fast alle Waffen nach echten Vorbildern neu gebaut, auch Werfer, Nahkampfwaffen und Granaten. 45 Oberflächen der Welt als echte Fotoscans, am Nachmittag 20 weitere. Soldaten mit modellierten Gesichtern und Mimik, Massenschlachten mit bis zu 250 Soldaten je Seite. Und die Kampagne „Stille Grenze“ begann: morgens drei Missionen mit Zwischensequenzen und deutscher Lippensynchronisation, abends die Grundausbildung und die Missionen 4 bis 6, kurz vor Mitternacht die Missionen 7 bis 11 bis zum offenen Ende von Akt II. Dazu zwei neue Karten, Flugplatz und Stadtkern, ein Jet, der von der Startbahn abhebt, und die Apps: PC-App, Web-App mit Offline-Speicher und Android.":"Почти всё оружие переделано по реальным образцам, включая гранатомёты, холодное оружие и гранаты. 45 поверхностей мира в виде настоящих фотосканов, днём ещё 20. Солдаты с проработанными лицами и мимикой, массовые сражения до 250 солдат с каждой стороны. И началась кампания «Тихая граница»: утром три миссии с катсценами и немецкой синхронизацией губ, вечером курс молодого бойца и миссии с 4 по 6, незадолго до полуночи – миссии с 7 по 11 до открытого финала второго акта. Плюс две новые карты, «Аэродром» и «Центр города», самолёт, взлетающий с полосы, и приложения: для ПК, веб-приложение с офлайн-хранилищем и Android.",
"Fast: ich, zusammen mit einer KI.":"Почти: я вместе с ИИ.",
"Februar":"Февраль",
"Feedback an den Entwickler":"Отзыв разработчику",
"Feedback an den Entwickler senden":"Отправить отзыв разработчику",
"Feedback freigeschaltet: Nach der Runde kannst du dem Entwickler Rückmeldung geben.":"Отзыв открыт: после раунда можно написать разработчику.",
"Feedback geben":"Оставить отзыв",
"Feedback:":"Отзыв:",
"Fehler":"Ошибка",
