"Feindkräfte":"Силы противника",
"Feindlichen Scharfschützen finden und ausschalten":"Найти и уничтожить вражеского снайпера",
"Feindliches Fahrzeug":"Вражеская техника",
"Feindliches HQ":"Штаб противника",
"Feindpanzer gesichtet!":"Вражеский танк обнаружен!",
"Feindpanzer in der Nähe ausschalten (optional)":"Подбить вражеские танки поблизости (необязательно)",
"Feindpanzer von Westen, auf dem Weg vom Gehöft! Ich kann den Turm nicht drehen – ihr müsst ihn zu Fuß stoppen!":"Вражеский танк с запада, по дороге от хутора! Я не могу повернуть башню – остановите его пешком!",
"Feine Schatten dort, wo Dinge den Boden berühren (Füße, Kisten, Leisten) – ergänzt die Schattenkarte. Ab „Hoch“.":"Тонкие тени в местах касания земли (ступни, ящики, плинтусы) – дополняют карту теней. С «Высокого».",
"Feld anklicken und eine Taste aus der Liste wählen. H = Haupthand (Waffe), N = Nebenhand. A/X ist die untere, B/Y die obere Taste.":"Щёлкните поле и выберите кнопку из списка. H = ведущая рука (оружие), N = вторая рука. A/X – нижняя кнопка, B/Y – верхняя.",
"Feld anklicken, dann Taste oder Maustaste drücken. Esc bricht ab. Bis zu drei Belegungen je Aktion.":"Щёлкните поле и нажмите клавишу или кнопку мыши. Esc – отмена. До трёх назначений на действие.",
"Feld antippen. Mitte schließt.":"Коснитесь поля. Центр – закрыть.",
"Feldbunker":"Полевой дот",
"Feldherr":"Полководец",
"Feldtelefon":"Полевой телефон",
"Feldwebel":"Старшина",
"Feldwebel Lenz":"Старшина Ленц",
"Feldwebel Martin Lenz":"Старшина Мартин Ленц",
"Feldwebel … Anker meldet Rauch über dem Brandwald. Das ganze Waldstück oberhalb des Holzplatzes steht in Flammen.":"Старшина… «Якорь» докладывает о дыме над лесом. Весь лесной участок над лесоскладом в огне.",
"Feldwebel … ich habe Kessars Funk entschlüsselt. Er zieht alles zusammen, was ihm folgt. Morgen früh, im Niemandsland.":"Старшина… я расшифровал рацию Кессара. Он стягивает всех, кто за ним идёт. Завтра утром, на Ничейной земле.",
"Feldwebel! Anker meldet: Das Funkrelais in Sant Aurel ist verstummt. Keine Verbindung mehr ins Tal.":"Старшина! «Якорь» докладывает: ретранслятор в Сант-Аурель замолчал. Связи с долиной больше нет.",
