"Fünfzehn Schuss, kaum Gewicht, blitzschnell gezogen. Die P-9 ist die verlässliche Antwort, wenn das Hauptmagazin leer ist.":"Пятнадцать патронов, почти без веса, мгновенно извлекается. P-9 – надёжный ответ, когда основной магазин пуст.",
"Fünfzig Schuss Vollgas. Kein Plan, nur Tempo.":"Пятьдесят патронов на полном газу. Никакого плана, только скорость.",
"Für Discord kopieren":"Скопировать для Discord",
"Für Fernseher und Konsolen: größere Schrift und Knöpfe, Abstand zum Bildschirmrand. Automatisch an im Xbox- und PlayStation-Browser und auf Fernsehern.":"Для ТВ и консолей: крупнее шрифт и кнопки, отступ от края экрана. Автоматически включается в браузерах Xbox и PlayStation и на телевизорах.",
"Für Gebäude, Treppen und enge Gassen. Ein Schuss pro Raum.":"Для зданий, лестниц и узких переулков. Один выстрел на комнату.",
"Für das Spiel wird JavaScript benötigt. Bitte aktiviere JavaScript in deinem Browser.":"Для игры нужен JavaScript. Включите его в браузере.",
"Für den Mehrspieler eine normale Internetverbindung. Offline läuft alles, was du schon einmal geladen hast.":"Для мультиплеера – обычное интернет-соединение. Офлайн работает всё, что уже загружалось.",
"Für dieses Gerät empfohlen: {0}. Mehr Bots können ruckeln und das Gerät warm machen.":"Для этого устройства рекомендуется: {0}. Больше ботов – возможны рывки и нагрев.",
"Für kleine Studios und für alle, die gerade erst anfangen, öffnet das eine Tür. Ein Spiel zu entwickeln verschlingt normalerweise viel Geld; selbst das größte Abo bei Claude ist günstiger als das, was die Entwicklung eines Indie-Spiels sonst kostet. Wer selbst programmieren kann, gibt dabei nichts aus der Hand: Er kann weiter eigene Wege gehen und prüfen, was die KI geschrieben hat. Und wer es nicht kann, so wie ich, bekommt überhaupt erst die Chance, aus einer Idee ein fertiges Spiel zu machen.":"Для небольших студий и для всех, кто только начинает, это открывает дверь. Разработка игры обычно поглощает много денег; даже самая дорогая подписка на Claude дешевле, чем обычно стоит разработка инди-игры. Кто умеет программировать сам, ничего не теряет: он может идти своим путём и проверять, что написал ИИ. А кто не умеет, как я, вообще впервые получает шанс превратить идею в готовую игру.",
"Für offline speichern":"Сохранить для офлайна",
