"Große Schlacht: ferne Soldaten werden vereinfacht gezeichnet. Für dieses Gerät empfohlen: {0}.":"Большое сражение: дальние солдаты рисуются упрощённо. Для этого устройства рекомендуется: {0}.",
"Großes Oktober-Update.":"Большое октябрьское обновление.",
"Großes Studio":"Большая студия",
"Großkalibrige Pistole mit sieben Patronen und spürbarem Hochschlag. Drei Treffer genügen auf kurze Distanz – zwei, wenn der erste den Kopf findet.":"Крупнокалиберный пистолет на семь патронов с заметным подбросом. Трёх попаданий хватает вблизи – двух, если первое пришлось в голову.",
"Großkampf auf weiter Karte: Nehmt die Flaggen A bis E ein, haltet sie und lasst den Gegner ausbluten. Jeder Wiedereinstieg kostet ein Ticket, wer mehr Flaggen hält, zieht dem Gegner laufend Tickets ab. Trupps zu viert, Einsatzkarte mit HQ-, Flaggen- und Truppspawns, Panzer und Geländewagen.":"Крупное сражение на большой карте: захватите флаги A–E, удержите их и обескровьте врага. Каждое возрождение стоит очко подкрепления; у кого больше флагов, тот постоянно отнимает очки у противника. Отделения по четыре, карта высадки со штабом, флагами и отделениями, танки и внедорожники.",
"Großkarte":"Большая карта",
"Großkarte mit Luftunterstützung (verbündete Jets überfliegen per air.spawn jet airborne)":"Большая карта с поддержкой авиации (пролёт союзных самолётов)",
"Großkarte ·":"Большая карта ·",
"Großkarte: Fluss mit Brücke, Dorf, Gehöft, Kieswerk und Funkhügel – fünf Flaggen.":"Большая карта: река с мостом, деревня, хутор, гравийный завод и радиохолм – пять флагов.",
"Großkarte: Schützengräben, Granattrichter, Stacheldraht, Ruinen – fünf Flaggen.":"Большая карта: окопы, воронки, колючая проволока, руины – пять флагов.",
"Großkarte: Startbahn, Hangars, Tower, Tanklager, Radar, Kaserne – Jets starten vom Boden.":"Большая карта: полоса, ангары, вышка, склад ГСМ, РЛС, казармы – самолёты взлетают с земли.",
"Großkarte: verbrannter Wald, Schützengräben mit Sandsäcken, Gittermasten – fünf Flaggen.":"Большая карта: сгоревший лес, окопы с мешками, опоры ЛЭП – пять флагов.",
"Großvater, wir sind an deiner Furt. Und diesmal kommen alle heim.":"Дед, мы у твоего брода. И на этот раз все вернутся домой.",
"Grundausbildung":"Курс молодого бойца",
"Grundausbildung (Mission 0)":"Курс молодого бойца (миссия 0)",
"Grundlage aller Optionen mit „Automatisch“.":"Основа для всех параметров «Автоматически».",
"Gruppen eins bis drei: Ruine nehmen. Keine Gefangenen, keine Zeugen.":"Группы с первой по третью: взять руины. Пленных не брать, свидетелей не оставлять.",
"Gräben mit Sandsackwänden, Brustwehren, Bretterverschalung, Wurzeln, Lattenrosten und Unterständen":"Окопы с брустверами из мешков, обшивкой из досок, корнями, настилами и блиндажами",
