"Größe des Leuchtpunkts in Leuchtpunkt- und Holo-Visieren (beim Holo nur der Mittelpunkt, der Ring bleibt).":"Размер точки в коллиматорных и голографических прицелах (у голо – только центр, кольцо остаётся).",
"Größe von Menüs und HUD-Anzeigen. Automatisch: 130 % im TV-Modus, sonst 100 %.":"Размер меню и интерфейса. Автоматически: 130 % в режиме ТВ, иначе 100 %.",
