"Gurt":"Лента",
"Gurt leer – Deckel öffnen (R)":"Лента пуста – открыть крышку (R)",
"Gurt leer – Gurtkasten wechseln ({0})":"Лента пуста – сменить коробку ({0})",
"Gurtgespeist, mit Zweibein und hundert Schuss Geduld. Der Hammer hält ganze Korridore dicht – solange ihn niemand beim langsamen Anlegen überrascht.":"Ленточное питание, сошки и сто патронов терпения. «Хаммер» держит целые коридоры – если никто не застанет его при медленной вскидке.",
"Gurtkasten":"Коробка с лентой",
"Gurtkasten tauschen (R) – noch {0} Gurtkästen":"Сменить коробку (R) – осталось {0}",
"Gurtkasten wechseln":"Сменить коробку с лентой",
"Gurtkasten wird getauscht …":"Меняю коробку с лентой…",
"Gut erkannt!":"Верно подмечено!",
"Gut gehalten. Ihre Infanterie ist erschöpft – jetzt brauchen wir das Funkgerät, bevor die Panzer kommen.":"Хорошо держались. Их пехота выдохлась – теперь нужна рация, пока не пришли танки.",
"Gut gemacht, Falke. Du hast heute niemanden verloren. Ruht euch aus – um fünf Uhr fliegt ihr nach Hagenmoor. Lenz besteht darauf, mitzukommen.":"Молодец, Фальке. Сегодня ты никого не потерял. Отдыхайте – в пять вылет на Хагенмор. Ленц настаивает, что полетит с вами.",
"Gut gemacht. Jetzt in die Löcher – und warten.":"Хорошо. Теперь в ячейки – и ждём.",
"Gut gemacht. Jetzt zum Tor – sie kommen gleich.":"Молодец. Теперь к воротам – они вот-вот будут.",
"Gut gemacht. Kommen Sie zum Vorplatz.":"Отлично. Подходите на площадку.",
"Gut getroffen!":"Хорошее попадание!",
"Gut so. Von hier siehst du den ganzen Nordplatz. Die Sitzung beginnt gleich.":"Хорошо. Отсюда видна вся северная часть площади. Заседание вот-вот начнётся.",
"Gut zu wissen":"Полезно знать",
"Gut. Die nächste Welle ist schon unterwegs – mit Schützenpanzern und Infanterie.":"Хорошо. Следующая волна уже идёт – с БМП и пехотой.",
"Gut. Jetzt schnell – sprinten Sie ein Stück.":"Хорошо. Теперь быстро – пробегитесь.",
"Gut. Motor läuft. Die Kanone ist geladen. Folge der Straße nach Süden.":"Хорошо. Двигатель работает. Пушка заряжена. Двигайся по дороге на юг.",
"Gut. Schub ganz nach vorn. Bleib auf der Mittellinie. Bei etwa zweihundertfünfzig Stundenkilometern ziehst du sanft – nicht reißen.":"Хорошо. Тягу до упора. Держись осевой. Примерно на двухстах пятидесяти км/ч плавно на себя – не дёргай.",
"Gut. Sender sitzt. Weiter nach Westen.":"Хорошо. Маяк стоит. Дальше на запад.",
"Gute Arbeit. Wir sehen sie jetzt alle. Dein Schuss – dann gehen wir rein.":"Отлично. Теперь видим всех. Твой выстрел – и заходим.",
