"Hafenkai, Grafikstufe Hoch: vor und nach der Runde für Gelände und Kleinkram (14. und 15. November).":"Причал, графика «Высокая»: до и после доработки рельефа и мелочей (14 и 15 ноября).",
"Hafennacht":"Ночь в гавани",
