"Haftet an jeder Oberfläche – und an jedem Gegner. Kürzere Zündzeit, kleinerer Radius, keine zweite Chance.":"Липнет к любой поверхности – и к любому врагу. Короче запал, меньше радиус, второго шанса нет.",
"Haftgranate":"Липкая граната",
"Halbautomatisch":"Полуавтоматический",
"Halbautomatische Präzision: zwei bis drei Treffer bis weit über 50 Meter.":"Полуавтоматическая точность: два-три попадания и далеко за 50 метров.",
"Halbautomatischer 40-mm-Granatwerfer mit Trommelmagazin für fünf Granaten – Sperrfeuer für den Pionier.":"Полуавтоматический 40-мм гранатомёт с барабаном на пять гранат – заградительный огонь для сапёра.",
"Halbautomatisches Anti-Material-Gewehr: zerreißt Deckung, Westen und leichte Fahrzeuge auf jede Entfernung. Dreizehn Kilo, ein Schlag wie ein Vorschlaghammer.":"Полуавтоматическая крупнокалиберная винтовка: рвёт укрытия, бронежилеты и лёгкую технику на любой дистанции. Тринадцать килограммов и удар как кувалдой.",
"Halbautomatisches Präzisionsgewehr mit 2,4-fachem Kompaktzielfernrohr. Zwei saubere Treffer bis gut 40 Meter, ein dritter auf weite Sicht – mehr braucht es nicht.":"Полуавтоматическая марксманская винтовка с компактным прицелом 2,4×. Два чистых попадания до 40 с лишним метров, третье – на дальней дистанции, больше не нужно.",
"Halbautomatisches Präzisionsgewehr mit Schalldämpfer über die ganze Lauflänge und schwerer Unterschallpatrone. Kaum hörbar, kein Mündungsfeuer, 3-fach-Visier – drei Treffer am Körper, Kopf und Brust genügen.":"Полуавтоматическая снайперская винтовка с глушителем во всю длину ствола и тяжёлым дозвуковым патроном. Почти не слышна, нет вспышки, прицел 3× — хватает трёх попаданий в корпус или в голову и грудь.",
"Halbautomatisches Präzisionsgewehr mit Schichtholzschaft und 4-fachem Kampfvisier: zwanzig Schuss im großen Kaliber, zwei Treffer bis weit hinaus. Schwer an der Schulter, ruhig im Anschlag.":"Полуавтоматическая марксманская винтовка с ложей из слоёной древесины и боевым прицелом 4×: двадцать патронов крупного калибра, два попадания далеко. Тяжела на плече, устойчива в прицеливании.",
