"Herausforderungen erfüllt":"Испытания выполнены",
"Herbst im Tal der Miren. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, sicherst Nachschub und kämpfst bei Nacht mit Wärmebild. Eine Mission spielt achtzig Jahre früher in einem alten Panzer.":"Осень в долине Мирен. С «Соколом-2» и своим экипажем ты прорываешь заградительные линии, удерживаешь высоту, обеспечиваешь снабжение и воюешь ночью с тепловизором. Одна миссия происходит на восемьдесят лет раньше в старом танке.",
"Herbst im Tal der Miren: Korvanische Panzer überschreiten die Grenze. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, geleitest Nachschub und schlägst bei Nacht zu.":"Осень в долине Мирен: корванские танки переходят границу. С «Соколом-2» и своим экипажем ты прорываешь заградительные линии, удерживаешь высоту, сопровождаешь снабжение и бьёшь ночью.",
"Herbst im Tal der Miren: Korvanische Panzer überschreiten die Grenze. Mit „Falke 2“ und deiner Besatzung brichst du durch Sperrlinien, hältst eine Höhe, geleitest Nachschub, schlägst bei Nacht zu – und erfährst, warum Oberfeldwebel Asmus die Furt von Mirenfurt so gut kennt.":"Осень в долине Мирен: корванские танки переходят границу. С «Соколом-2» и своим экипажем ты прорываешь заградительные линии, удерживаешь высоту, сопровождаешь снабжение, бьёшь ночью – и узнаёшь, почему прапорщик Асмус так хорошо знает брод у Миренфурта.",
"Herr Hauptmann – Kessar sendet. Auf allen Frequenzen gleichzeitig.":"Товарищ капитан – Кессар выходит в эфир. На всех частотах сразу.",
"Herr Hauptmann – jemand ist auf unserer Frequenz. Offener Kanal, ohne Schlüssel.":"Товарищ капитан – кто-то на нашей частоте. Открытый канал, без шифра.",
"Herr Hauptmann … jemand ist auf unserer offenen Frequenz. Kein Rufzeichen. Das Signal kommt nicht aus dem Tal.":"Товарищ капитан… кто-то на нашей открытой частоте. Без позывного. Сигнал идёт не из долины.",
"Herr Hauptmann! Das Relais in Sant Aurel – Kessars Leute haben es besetzt. Er will heute Nacht senden, auf allen Kanälen.":"Товарищ капитан! Ретранслятор в Сант-Аурель – люди Кессара его захватили. Он хочет выйти в эфир этой ночью на всех каналах.",
"Herrschaft":"Господство",
"Herunterladen":"Скачать",
"Herunterschalten (Panzer)":"Передача вниз (танк)",
"Hetzer":"Бегун",
"Heute":"Сегодня",
"Heute Nacht greifen wir ihr Lager an der Behelfsbrücke an. Dafür bekommt ihr Falke 2 zurück – mit Wärmebild.":"Этой ночью атакуем их лагерь у временного моста. Для этого вам вернут «Сокол-2» – с тепловизором.",
"Hiebdauer":"Время удара",
"Hier Daren, offener Kanal. Ich habe den Befehl erhalten. Ich werde ihn nicht ausführen.":"Говорит Дарен, открытый канал. Приказ получен. Я не буду его выполнять.",
"Hier Hof. Alles ruhig.":"Говорит «Хутор». Всё тихо.",
"Hier Oberst Vesk an die veldmärkischen Truppen. Wir räumen Mirenfurt. Ich bitte um Waffenruhe für unsere Verwundeten.":"Говорит полковник Веск, вельдмаркским войскам. Мы оставляем Миренфурт. Прошу прекращения огня для наших раненых.",
"Hier Rabe 7 – feindliche Panzer an der Linie! Erbitten Feuer auf Planquadrat Mirenfurt Nord!":"Здесь «Ворон-7» – вражеские танки у линии! Просим огонь по квадрату Миренфурт-Север!",
"Hier Vahl. Der Hügel ist verloren. Plan bleibt. Mittag, Lindenplatz. Niemand redet.":"Говорит Валь. Холм потерян. План в силе. Полдень, Линденплац. Никто не болтает.",
"Hier haben vor hundert Jahren Männer auf beiden Seiten in Gräben gelegen. Wenn wir hier unterschreiben, versteht jeder, worum es geht.":"Сто лет назад здесь в окопах лежали люди с обеих сторон. Если подпишем здесь, все поймут, о чём речь.",
"Hier halten wir. Gräben besetzen, die Leute runter in den Graben!":"Держимся здесь. Занять окопы, людей – вниз, в траншею!",
"Hier herunterladen":"Скачать здесь",
"Hier ist es. Die Antenne ist abgerissen – gib mir einen Moment.":"Вот она. Антенна оторвана – дай минуту.",
"Hier ist kein Platz zum Bauen.":"Здесь негде строить.",
"Hier liegt ein Funkgerät mit Schlüsselliste. Das brauche ich – gib mir Deckung, Falke.":"Здесь рация со списком ключей. Мне это нужно – прикрой, Фальке.",
"Hier schießt niemand mehr. Wo ist Kessar?":"Здесь больше никто не стреляет. Где Кессар?",
"Hier spielen":"Играть здесь",
"Hier spricht Major Ilja Daren, Ostbund, Dritte Grenzbrigade. An alle Einheiten beider Seiten.":"Говорит майор Илья Дарен, Восточный союз, Третья пограничная бригада. Всем подразделениям обеих сторон.",
"Hier spricht Major Ilja Daren, Ostbund, Dritte Grenzbrigade. Ich weiß, was Oberst Kessar vorhat.":"Говорит майор Илья Дарен, Восточный союз, Третья пограничная бригада. Я знаю, что задумал полковник Кессар.",
"Hier spricht Oberst Kessar. Wer das Funkhaus betritt, ist für jeden Toten darin verantwortlich.":"Говорит полковник Кессар. Кто войдёт в радиодом, ответит за каждого погибшего внутри.",
"Hier! Wir sind hier drin! Nicht schießen!":"Сюда! Мы здесь! Не стреляйте!",
"Hierher":"Сюда",
