"Hinter der Sperrlinie":"За заградительной линией",
"Hinterhalt":"Засада",
"Hinterhalt im Dorf zerschlagen":"Разбить засаду в деревне",
"Hinterhalt mit Pak und Infanterie zerschlagen":"Разгромить засаду из ПТО и пехоты",
"Hinterhalt! Raus aus den Wagen, in die Häuser! Hofer, bleib beim Major!":"Засада! Из машин – в дома! Хофер, останься с майором!",
"Hinterhöfe mit Toreinfahrten, Schuppen und Linden":"Дворы с подворотнями, сараями и липами",
