"Im Schießstand ist jede Waffe frei. Der Parcours misst deine Bestzeit.":"На стрельбище доступно любое оружие. Полоса фиксирует ваш рекорд.",
"Im Spiel liegen die Knöpfe genau hier; Größe und Lage folgen den Rändern deines Telefons.":"В игре кнопки находятся именно здесь; размер и положение подстраиваются под края телефона.",
"Im Sprint: Rutschen.":"На бегу: подкат.",
"Im Stil „Klassisch“ ohne Nachschärfen.":"В стиле «Классический» без повышения резкости.",
"Im Stil „Realismus“ ausgeblendet.":"Скрыто в стиле «Реализм».",
"Im Vollbild starten":"Запускать в полноэкранном режиме",
"Im Waffenspiel einen Gegner per Messer zurückgestuft.":"В «Гонке вооружений» понизили врага ножом.",
"Im Waffenspiel wirft dich ein Messerabschuss eine Stufe zurück.":"В «Гонке вооружений» убийство ножом отбрасывает на уровень назад.",
"Im Werk laufen die Pumpen für das ganze Tal. Dort arbeiten dreihundert Leute, viele mit ihren Familien.":"На заводе насосы для всей долины. Там работают триста человек, многие с семьями.",
"Im Übungsgelände fährst und schießt du jeden Panzer frei (Sitzwechsel im Fahrzeug). Für Simulation mit Handgriffen, Rolle und KI-Besatzung startet der Modus „Panzer“ auf dieser Karte: eigene Feuerstellung an der Panzerschießbahn, leichte Feindkräfte im Zielraum. Sonst: Lobby → Reiter „Panzer“.":"На полигоне ты свободно ездишь и стреляешь на любом танке (смена места в машине). Для симуляции с действиями, ролью и ИИ-экипажем на этой карте запускается режим «Танки»: своя огневая позиция на танковом стрельбище, лёгкие силы противника в районе целей. Иначе: Лобби → вкладка «Танки».",
"Immer":"Всегда",
