"In der Verlängerung entschieden":"Решилось в овертайме",
"In die Stadt. Er sucht sich Menschen, hinter denen er sich verstecken kann.":"В город. Ищет людей, за которыми можно спрятаться.",
"In diesem Link steckt kein Raumcode – er sieht so aus: …spielen.html?raum=K7M2QX":"В ссылке нет кода комнаты – он выглядит так: …spielen.html?raum=K7M2QX",
"In diesem Modus nicht verfügbar – es gilt „Realistisch“.":"Недоступно в этом режиме – действует «Реализм».",
"In diesen zwei Wochen ist keine neue Fassung erschienen.":"За эти две недели не вышло ни одной новой версии.",
