"In neuem Tab öffnen":"Открыть в новой вкладке",
"In seiner Jacke: ein Notizbuch. Zahlungen, Daten, Treffpunkte. Und immer derselbe Absender – „Kranich“.":"В его куртке – блокнот. Выплаты, даты, места встреч. И всегда один отправитель – «Кранич».",
