"Infiziere 50 Überlebende.":"Заразите 50 выживших.",
"Infiziere {n} Überlebende":"Заразите {n} выживших",
"Infiziert":"Заражение",
"Infiziert und Waffenspiel gingen online, jede Klasse bekam eine eigene Fähigkeit, im Realismus-Modus muss man Munition bei Gefallenen aufsammeln, und Pioniere können Sandsäcke, MG-Nester und Bunker bauen. Die Waffen bekamen mehr Details. Dazu kam eine neue Karte: eine Zauberbibliothek in einer Steinhalle mit verwinkelten Regalgassen, Galerien und Brücken.":"Вышли «Заражение» и «Гонка вооружений», каждый класс получил свою способность, в реалистичном режиме патроны надо собирать с павших, а сапёры могут строить мешки с песком, пулемётные гнёзда и доты. Оружие стало детальнее. Плюс новая карта: волшебная библиотека в каменном зале с извилистыми проходами между стеллажами, галереями и мостиками.",
"Infizierte":"Заражённые",
"Infizierte Überlebende":"Заражено выживших",
"Infizierte: Messer, Haftgranate, schneller zurück":"Заражённые: нож, липкая граната, быстрее возрождаются",
"Innere Totzone (Controller)":"Внутренняя мёртвая зона (контроллер)",
"Inspizieren":"Осмотр",
"Installiert – du spielst gerade in der Web-App.":"Установлено – вы сейчас играете в веб-приложении.",
"Installiert. NULLPUNKT liegt jetzt bei deinen Apps.":"Установлено. NULLPUNKT теперь среди ваших приложений.",
"Instandsetzung Nord · Nr. 4471":"Ремонт «Север» · № 4471",
"Interagieren":"Действие",
"Interagieren (Parcours im Schießstand)":"Взаимодействие (полоса на стрельбище)",
"Interagieren, einsteigen":"Взаимодействие, посадка",
