"Ist deine Vorgabe":"Ваш выбор по умолчанию",
"Ist nicht so schlimm, wie es aussieht … Bring den Major hoch, Falke. Das ist wichtiger.":"Не так страшно, как выглядит… Доставь майора наверх, Фальке. Это важнее.",
"JK-9 Falke: Kampfjet mit Bordkanone, Raketen und Bomben. Auf dem Fliegerhorst startet er von der Bahn.":"JK-9 Falke: истребитель с пушкой, ракетами и бомбами. На авиабазе взлетает с полосы.",
"Ja":"Да",
"Ja, der Arm hängt in der Schlinge. Schießen kann ich mit der anderen Hand. Diskussion beendet.":"Да, рука на перевязи. Стрелять могу другой. Разговор окончен.",
"Jagdpanzer":"Истребитель танков",
"Januar":"Январь",
"Jaro Vahl lebend festnehmen":"Взять Яро Валя живым",
"Je 25 Abschüsse mit 10 verschiedenen Waffen.":"По 25 убийств из 10 разных видов оружия.",
"Je nach Karte (Niemandsland: 1. Weltkrieg, sonst modern)":"Зависит от карты (Ничейная земля: Первая мировая, иначе современность)",
"Jede Klasse hat drei Ausführungen. Die Teamfarbe an Ärmel und Helm bleibt immer erkennbar.":"У каждого класса три варианта. Цвет команды на рукаве и шлеме всегда заметен.",
"Jede Waffe hat ihren eigenen Schnitt.":"У каждого оружия свой профиль.",
"Jede Waffe ist hier frei – auch noch gesperrte zum Probeschießen. Reserve unbegrenzt.":"Здесь доступно любое оружие, даже закрытое – для пробной стрельбы. Запас бесконечен.",
"Jede gehaltene Flagge: 1 Punkt alle 4 Sekunden":"Каждый удерживаемый флаг: 1 очко каждые 4 секунды",
"Jeder Abschuss befördert dich zur nächsten Waffe – von der MP über das Scharfschützengewehr bis zum Kampfmesser. Wer mit der letzten Stufe trifft, gewinnt. Ein Messerabschuss wirft das Opfer eine Stufe zurück.":"Каждое убийство переводит на следующее оружие – от ПП через снайперскую винтовку до боевого ножа. Побеждает тот, кто убьёт на последнем уровне. Убийство ножом отбрасывает жертву на уровень назад.",
"Jeder Abschuss bringt Munition für die Waffe, mit der er gelang: ein Magazin, beim Maschinengewehr 20 Schuss direkt in den Gurt. Der Vorrat wächst höchstens ein Magazin über den Startwert. Online entscheidet der Host.":"Каждое убийство даёт патроны для оружия, которым оно сделано: магазин, у пулемёта – 20 патронов прямо в ленту. Запас растёт не более чем на магазин сверх начального. Онлайн решает хост.",
"Jeder Abschuss bringt ein Magazin (MG: 20 Schuss)":"Каждое убийство даёт магазин (пулемёт: 20 патронов)",
"Jeder Ausgeschaltete verliert seine Erkennungsmarke. Sammle die Marken der Gegner ein, um Abschüsse zu bestätigen – und schnapp dir die Marken deiner Kameraden, bevor der Gegner es tut. Wer nur aus der Ferne schießt, punktet nicht.":"Каждый убитый роняет свой жетон. Подбирайте жетоны врагов, чтобы подтвердить убийства, – и успевайте забрать жетоны товарищей раньше противника. Кто стреляет только издалека, очков не получает.",
"Jeder Handgriff selbst, keine Außenansicht, KI-Besatzung auf den anderen Plätzen.":"Каждое действие сам, без внешнего вида, ИИ-экипаж на остальных местах.",
"Jeder Handgriff selbst, keine Außenansicht.":"Каждое действие сами, без внешнего вида.",
"Jeder Wiedereinstieg kostet ein Ticket":"Каждое возрождение стоит очко подкрепления",
"Jeder eingesetzte Soldat kostet ein Verstärkungsticket":"Каждый высаженный боец стоит очко подкреплений",
"Jeder für sich":"Каждый сам за себя",
"Jeder für sich, 30 bis 60 Teilnehmer je nach Gerät":"Каждый сам за себя, от 30 до 60 участников в зависимости от устройства",
"Jeder gegen jeden":"Каждый сам за себя",
"Jedes Wort ist eine Wahl.":"Каждое слово – выбор.",
"Jet-Einsatz":"Вылет на самолёте",
"Jet: Start von der Bahn, Luftkampf gegen Hubschrauber":"Самолёт: взлёт с полосы, воздушный бой с вертолётами",
"Jet: W/S Schub, Maus neigen/rollen, A/D Seitenruder. Auf der Bahn Vollgas, ab etwa 250 km/h sanft ziehen.":"Самолёт: W/S тяга, мышь тангаж/крен, A/D руль направления. На полосе полный газ, примерно с 250 км/ч плавно на себя.",
"Jetzt die zweite Stellung. Sie haben uns gehört – Verstärkung kommt!":"Теперь вторая позиция. Нас услышали – идёт подкрепление!",
"Jetzt neu starten":"Перезапустить",
"Jetzt neu starten und installieren":"Перезапустить и установить сейчас",
"Jetzt sind Sie raus. Das zählt.":"Теперь вы выбрались. Это главное.",
"Jetzt weißt du es.":"Теперь вы знаете.",
"Jetzt wird es laut, egal wie leise wir sind. Auf dein Zeichen, Falke!":"Сейчас будет шумно, как бы тихо мы ни шли. По твоему сигналу, Фальке!",
"Joystick":"Джойстик",
"Joystick. Er erscheint, wo dein linker Daumen landet; ganz nach oben geschoben sperrt er den Sprint.":"Джойстик. Появляется там, где лёг левый большой палец; сдвинутый до упора вверх фиксирует спринт.",
