"Kampfgewehr im großen Kaliber: vier Treffer auf jede Distanz, durchschlägt Deckung, die andere aufhält. Zwanzig Schuss und ein Rückstoß, der Respekt verlangt.":"Боевая винтовка крупного калибра: четыре попадания на любой дистанции, пробивает укрытия, которые держат другое. Двадцать патронов и отдача, требующая уважения.",
