"Kein Fahrzeug verfügbar – dieser Teil entfällt.":"Техники нет – этот этап пропускается.",
"Kein Gamepad erkannt. Drück eine Taste am Controller.":"Геймпад не найден. Нажми кнопку на контроллере.",
"Kein HUD, kein Fadenkreuz. Magazine zählen einzeln, halbleere bleiben halbleer. Du lädst durch, sicherst, behebst Ladehemmungen und stellst das Visier auf die Entfernung ein. Treffer verwunden einzelne Körperteile, Blutungen stillst du mit Verband oder Abbinden, und wer zu viel Blut verliert, wird bewusstlos.":"Без HUD и прицельной метки. Магазины считаются поштучно, полупустые остаются полупустыми. Ты досылаешь патрон, ставишь на предохранитель, устраняешь задержки и выставляешь прицел на дальность. Попадания ранят отдельные части тела, кровотечение останавливаешь повязкой или жгутом, а потерявший слишком много крови теряет сознание.",
"Kein Helm":"Без шлема",
