"Kein Licht, kein Funk ohne Not. Im Wärmebild sehen wir ihre Motoren lange bevor sie uns hören.":"Без света, без радио без нужды. В тепловизоре мы увидим их моторы задолго до того, как они нас услышат.",
"Kein Magazin eingesetzt":"Магазин не вставлен",
"Kein Pionier im Trupp.":"В отделении нет сапёра.",
"Kein Plattenträger: volle Beweglichkeit, jeder Treffer geht aufs Leben.":"Без бронежилета: полная подвижность, каждое попадание – по здоровью.",
