"Kompakt, ruhig im Dauerfeuer und schneller im Anschlag als jeder Gegner, der um die Ecke kommt. Die Viper beißt zu, bevor das Gegenüber blinzelt – und bleibt bis in die Hofmitte gefährlich.":"Компактный, стабильный на очередях и быстрее в прицеливании, чем любой враг из-за угла. «Випер» жалит раньше, чем противник моргнёт, – и опасен до середины двора.",
"Kompakte Maschinenpistole mit Rückstoßumlenkung und über tausend Schuss pro Minute. Auf Türrahmen-Distanz ein Sturm – auf der Straße nur noch ein Summen.":"Компактный ПП с отводом отдачи и более чем тысячей выстрелов в минуту. На дистанции двери – буря, на улице – лишь жужжание.",
