"Korvanische Panzer haben in der Nacht die Grenze überschritten. Brich mit Falke 1 durch ihre Sperrlinie aus Pak-Stellungen, Bunker und Panzern und zerstör die Funkstelle, die ihre Artillerie lenkt.":"Ночью корванские танки перешли границу. Вместе с «Соколом-1» прорви их заградительную линию из ПТО, дотов и танков и уничтожь радиоточку, которая наводит их артиллерию.",
