"Kurze Axt mit breitem Bart: ein Hieb genügt, und er geht durch Helm und Weste. Spezial „Wucht“: der Getroffene taumelt, Umstehende im Bogen bekommen den halben Schaden. Langsam, schwer, unaufhaltsam.":"Короткий топор с широкой бородкой: хватает одного удара, и он проходит сквозь шлем и бронежилет. Особое «Мощь»: жертва шатается, стоящие в дуге получают половину урона. Медленно, тяжело, неудержимо.",
