"Kurzkarabiner im Kaliber 7,62 × 39 mit Klappschaft: schwere Kugel aus kurzem Lauf, laut und grell. Im Haus ein Hammer – auf der Straße streut er früher als die langen Gewehre.":"Укороченный карабин калибра 7,62 × 39 со складным прикладом: тяжёлая пуля из короткого ствола, громко и ярко. В доме – молот, на улице рассеивает раньше длинных винтовок.",
