"Libelle 1":"Либелле 1",
"Libelle 1 an Falke: Er ist unten. Du kannst jetzt aufhören, über ihn hinwegzudonnern. Landebahn ist frei – mach es ordentlich.":"«Либелле 1» – Фальке: он сел. Можешь перестать проноситься над ним. Полоса свободна – садись аккуратно.",
