"Libelle 1 ist abgestürzt.":"«Либелле 1» разбился.",
"Libelle 1 ist aufgetankt. Am Holzplatz steht Flugabwehr – zwei, drei Nester, vielleicht mehr. Ich kann nicht landen, solange die feuern.":"«Либелле 1» заправлен. У лесосклада зенитки – два-три гнезда, может, больше. Пока они стреляют, я не сяду.",
"Libelle 1, Kurs auf die Landezone. Noch zwei Minuten.":"«Либелле 1», курс на зону высадки. Ещё две минуты.",
"Licht":"Свет",
"Licht und Farben wurden an einem echten Video gemessen und nachgestellt: Pflaster, Dächer, Putz, Wellblech und Ziegel in diesem Stil, ein bewölkter Himmel als Standard, ein dichteres Dorf im Grenzland mit zehn eingerichteten Häusern und begehbare Hallen im Hafen. Die Soldaten bekamen Splittertarn, große Helme und Rucksäcke. Dazu die ersten Zivilfahrzeuge zum Selbstfahren: Limousine, Kastenwagen, Gabelstapler und Sattelzug.":"Свет и цвета измерили по настоящему видео и воссоздали: брусчатка, крыши, штукатурка, профнастил и кирпич в этом стиле, пасмурное небо по умолчанию, более плотная деревня в «Пограничье» с десятью обставленными домами и доступные цеха в «Гавани». Солдаты получили «осколочный» камуфляж, большие шлемы и рюкзаки. Плюс первые гражданские машины, которые можно водить: седан, фургон, вилочный погрузчик и седельный тягач.",
