"Major Daren muss lebend vor die Waffenstillstandskommission. Sichere die Kolonne am MG des Geländewagens, zerschlag den Hinterhalt im Dorf und bring Daren zum Nordhang.":"Майор Дарен должен живым предстать перед комиссией. Прикройте колонну с пулемёта внедорожника, разбейте засаду в деревне и доставьте Дарена на северный склон.",
"Major Daren. Die Kommission hat Ihre Unterlagen gelesen. Ihnen ist klar, dass Sie damit Ihre Laufbahn beenden?":"Майор Дарен. Комиссия ознакомилась с вашими документами. Вы понимаете, что этим заканчиваете карьеру?",
