"Markier sie mir, Falke. Ich hole sie leise raus, einen nach dem anderen. Und wenn du dir nicht sicher bist – dann bist du dir nicht sicher.":"Отметь их мне, Фальке. Я тихо выведу их по одному. А если не уверен – значит, не уверен.",
