"Maschinenpistole":"Пистолет-пулемёт",
"Maschinenpistole der Weltkriegszeit aus Stahlrohr und Bakelit: gemächlicher Takt, gutmütig im Dauerfeuer, zweiunddreißig Schuss im Stangenmagazin. Der Magazinschacht ist zugleich der Vordergriff.":"ПП времён мировой войны из стальной трубы и бакелита: неторопливый темп, послушен на очередях, тридцать два патрона в коробчатом магазине. Приёмник магазина служит и передней рукоятью.",
"Maschinenpistole im Kaliber 9 mm mit Doppeltrommel für fünfundneunzig Patronen. Wer den Abzug hält, hält ihn lange; die volle Trommel macht sie kopflastig, und der Wechsel dauert, bis jemand anders zuerst schießt.":"Пистолет-пулемёт 9 мм со сдвоенным барабаном на девяносто пять патронов. Кто зажал спуск — держит его долго; полный барабан перевешивает вперёд, а смена длится так долго, что кто-то другой успевает выстрелить первым.",
"Maschinenpistole mit eingebautem Schalldämpfer über die ganze Lauflänge: kein Mündungsfeuer, kaum ein Knall – nur das Klacken des Verschlusses. Leise ist sie nicht wehrlos, aber auf Distanz verliert sie schnell an Wucht.":"ПП с интегрированным глушителем по всей длине ствола: без вспышки, почти без хлопка – только лязг затвора. Тихий не значит беззащитный, но на дистанции быстро теряет силу.",
