"Mediterrane Gassen, Markt und Dachterrassen in der Mittagssonne.":"Средиземноморские улочки, рынок и террасы на крышах под полуденным солнцем.",
"Mehr Bilder pro Sekunde auf allen Geräten, Versorgungsstationen auf den Karten, Panzer schieben Gebäude ein, detailliertere Soldaten.":"Больше кадров в секунду на всех устройствах, пункты снабжения на картах, танки сносят здания, солдаты детальнее.",
"Mehr Bilder pro Sekunde auf allen Geräten, Versorgungsstationen, und Panzer reißen jetzt Gebäude ein.":"Больше кадров в секунду на всех устройствах, пункты снабжения, и танки теперь сносят здания.",
