"Mehrspieler ist gerade nicht verfügbar – das Netzmodul wurde nicht geladen. Seite neu laden und es noch einmal versuchen.":"Мультиплеер недоступен – сетевой модуль не загрузился. Перезагрузите страницу и попробуйте снова.",
"Mehrspieler und VR.":"Мультиплеер и VR.",
"Mehrspieler · Vorgaben aus „Einsatz“":"Мультиплеер · настройки из «Боя»",
"Mehrspieler → Beitreten":"Мультиплеер → Войти",
"Mehrspieler: Browser-, Handy- und VR-Spieler sind in denselben Räumen, wenn alle dieselbe Spielfassung haben. Einladungslinks aus der App führen auf die Webseite.":"Мультиплеер: игроки в браузере, на телефоне и в VR попадают в одни комнаты, если у всех одна версия. Ссылки-приглашения из приложения ведут на сайт.",
"Mehrstöckiger Häuserkampf":"Бой в многоэтажных зданиях",
"Mehrzweck":"Универсальный",
"Mehrzweckgranate":"Многоцелевой",
"Meilensteine":"Вехи",
"Mein Befehl lautete, heute Morgen mit Kessar zu marschieren. Ich habe ihn verweigert. Zweihundert meiner Leute auch.":"Мне приказали сегодня утром выступить с Кессаром. Я отказался. И двести моих людей тоже.",
"Mein Bein trägt mich noch nicht in ein Cockpit. Aber auf der Bahn steht ein JK-9, vollgetankt. Falke, du hattest zwölf Stunden im Simulator in Hohenfeld.":"Нога пока не донесёт меня до кабины. Но на полосе стоит заправленный JK-9. Фальке, у тебя было двенадцать часов на тренажёре в Хоэнфельде.",
"Mein Großvater Emil war zweiundzwanzig. Sein Panzer hieß Bison, und sein Zielfernrohr war alles, was er hatte.":"Моему деду Эмилю было двадцать два. Его танк звался «Bison», и прицел был всем, что у него было.",
"Mein Großvater hat einmal gesagt: An der Furt von Mirenfurt entscheidet sich jeder Krieg in diesem Tal. Er war dabei – vor achtzig Jahren.":"Мой дед однажды сказал: у брода Миренфурт решается любая война в этой долине. Он был там – восемьдесят лет назад.",
"Mein Ziel war von Anfang an: so realistisch wie möglich, irgendwo zwischen CS:GO, Battlefield und Bodycam. An diesem Tag kamen der Hafen und das Werk dazu, Bots, die Deckung suchen und flankieren, Fotoscan-Texturen und echte Tonaufnahmen für die Waffen. Weil ich auch Fahrzeuge wollte, entstand die große Karte Grenzland mit Dorf, Bauernhof, Industrie und einer Brücke, samt ein paar versteckten Geheimnissen.":"Моя цель с самого начала: максимально реалистично, где-то между CS:GO, Battlefield и Bodycam. В тот день появились «Гавань» и «Завод», боты, которые ищут укрытия и заходят с флангов, фотосканированные текстуры и настоящие записи звуков оружия. Поскольку я хотел ещё и технику, появилась большая карта «Пограничье» с деревней, фермой, промзоной и мостом – и парой спрятанных секретов.",
"Meine Brigade hält die Straße nach Osten. Aber die Graue Kompanie kommt nicht über Straßen. Sie kommt durch die Trichter.":"Моя бригада держит дорогу на восток. Но «Серая рота» по дорогам не ходит. Она идёт через воронки.",
"Meine Freunde testen.":"Друзья тестируют.",
"Meine Laufbahn ist mir weniger wert als die Menschen in diesem Tal.":"Моя карьера стоит меньше, чем люди этой долины.",
"Meine Leute haben heute gegen Männer gekämpft, mit denen sie gestern noch gegessen haben. Das vergessen sie nicht.":"Сегодня мои люди сражались с теми, с кем ещё вчера ели за одним столом. Они этого не забудут.",
"Meine Leute? Ilja, du verstehst es immer noch nicht. Ich war nie derjenige, der bezahlt hat.":"Мои люди? Илья, ты так и не понял. Я никогда не был тем, кто платил.",
