"Mirenfurt: Gassen, Dächer, Brücken. Mit dem Infanteriezug von Leutnant Wendt rückst du durch die Stadt vor. Panzerabwehrtrupps lauern in den Häusern – die Infanterie schützt dich, du schützt die Infanterie.":"Миренфурт: переулки, крыши, мосты. Ты продвигаешься через город вместе с пехотным взводом лейтенанта Вендта. В домах затаились противотанковые группы – пехота прикрывает тебя, ты прикрываешь пехоту.",
