"Mit Kinnschutz: halbiert Kopftreffer und hält deutlich länger. Scharfschützen unter 25 m schlagen trotzdem durch.":"С защитой подбородка: вдвое снижает урон в голову и держится гораздо дольше. Снайперы ближе 25 м всё равно пробивают.",
