"Mit „+“ verbundene Tasten: die erste halten, dann die zweite drücken. Am Fernseher schaltet das Spiel den TV-Modus mit großer Schrift ein.":"Кнопки через «+»: удерживай первую, затем нажми вторую. На телевизоре игра включает ТВ-режим с крупным шрифтом.",
