"Muss man sich vor KI fürchten? Ich finde nicht. Mit Respekt sollte man ihr aber begegnen: Sie entwickelt sich rasant, und es lohnt sich, wachsam zu bleiben, wohin die Reise in den kommenden Jahren geht. Das ändert nichts daran, dass wir heute leben, und heute kann KI genau die Lücken füllen, die man selbst hat. Bei mir war das das Programmieren.":"Нужно ли бояться ИИ? Я думаю, нет. Но относиться к нему стоит с уважением: он развивается стремительно, и стоит внимательно следить, куда всё пойдёт в ближайшие годы. Это не отменяет того, что мы живём сегодня, а сегодня ИИ может закрыть именно те пробелы, которые есть у тебя самого. У меня это было программирование.",
