"Nur Spieldateien (Code, Texturen, Modelle), damit die Seite schneller lädt und offline läuft. Keine persönlichen Daten":"Только файлы игры (код, текстуры, модели), чтобы страница грузилась быстрее и работала офлайн. Никаких личных данных",
