"Nur für Spieler der ersten Stunde (bis 13.10.2026) – ein Dankeschön, nicht mehr freischaltbar.":"Только для игроков с первых дней (до 13.10.2026) – в знак благодарности, больше не открывается.",
"Nur für Spieler der ersten Stunde. Bis zu drei eigene Muster – danach in der Tarnungsauswahl jeder Waffe. Online sehen die anderen dein Muster.":"Только для игроков с первых дней. До трёх своих узоров – затем они доступны в выборе камуфляжа любого оружия. Онлайн другие видят ваш узор.",
"Nur für Spieler der ersten Stunde: Karabiner mit goldenen Ringen und dem Nullpunkt-Zeichen. Liegt zwischen M-17 und K-36 – etwas mehr Wucht als der K-36, etwas langsamer – ruhig im Dauerfeuer, keine Wunderwaffe.":"Только для игроков с первых дней: карабин с золотыми кольцами и знаком Nullpunkt. Между M-17 и K-36 – чуть мощнее K-36, чуть медленнее, стабилен на очередях, но не чудо-оружие.",
"Nur für Spieler der ersten Stunde: Pistole mit goldenem Kompensator. Etwas mehr Wucht und weniger Rückstoß als die P-9, dafür ein Schuss weniger im Magazin.":"Только для игроков с первых дней: пистолет с золотым компенсатором. Чуть мощнее и с меньшей отдачей, чем P-9, но на патрон меньше в магазине.",
"Nur für Spieler der ersten Stunde: zweischneidiger Dolch mit goldener Parierstange. Zwei Stiche wie das Kampfmesser, von hinten einer – etwas schneller im Stoß, dafür kürzer.":"Только для игроков с первых дней: обоюдоострый кинжал с золотой гардой. Два удара, как у боевого ножа, со спины один – чуть быстрее укол, но короче.",
