"Nur wenn du einen Raum öffnest oder beitrittst, verlassen Daten das Gerät; NULLPUNKT selbst speichert davon nichts. Den Verbindungsaufbau vermitteln öffentliche Nostr-Relays (verschlüsselt, ohne Konto), STUN-Server von Google und Cloudflare helfen beim Finden der Verbindung. Danach spielen die Browser direkt miteinander (WebRTC) – dabei sehen die Mitspieler im Raum technisch deine IP-Adresse. Sichtbar sind außerdem dein Spielername, Team, Stufe und Gerät. Öffentliche Spiele stehen mit Raumcode, Name des Hosts und Karte in einer öffentlichen Liste. Einen eigenen Spielserver gibt es nicht.":"Данные покидают устройство, только когда вы открываете комнату или входите в неё; сам NULLPUNKT ничего из этого не хранит. Соединение устанавливают публичные реле Nostr (шифрованно, без аккаунта), STUN-серверы Google и Cloudflare помогают найти путь. Затем браузеры играют напрямую (WebRTC) – при этом другие игроки в комнате технически видят ваш IP-адрес. Также видны ваше имя игрока, команда, уровень и устройство. Публичные игры отображаются в открытом списке с кодом комнаты, именем хоста и картой. Отдельного игрового сервера нет.",
