"Panzerabwehr-Rohr der Pioniere: Raketengranate mit Hohlladung. Knackt Geländewagen mit einem Treffer in die Flanke, Kampfpanzer mit zweien ins Heck – und räumt jede Stellung.":"Противотанковая труба саперов: реактивная граната с кумулятивным зарядом. Внедорожник – одним попаданием в борт, танк – двумя в корму, и любая позиция зачищена.",
