"Panzerbesatzung":"Танковый экипаж",
"Panzerbesatzung: leichte Weste, MP und Pistole, Rauch- und Splittergranate, Fernglas; wechselt im Panzer doppelt so schnell den Sitz, lädt 25 % schneller und repariert das eigene Fahrzeug im Notfall.":"Танкист: лёгкий жилет, ПП и пистолет, дымовая и осколочная гранаты, бинокль; в танке пересаживается вдвое быстрее, заряжает на 25 % быстрее и в крайнем случае чинит свою машину.",
