"Programmieren ist dabei nur ein Einsatzgebiet. KI kann zum Beispiel auch Musik erzeugen, das sehe ich allerdings kritischer, denn Musik ist für mich echte Kunst. Programmieren ist für mich eher Handwerk: Hobby, Leidenschaft und eine Frage des Könnens. Weil mir genau dieses Können fehlt, habe ich mir Claude an die Seite geholt.":"Программирование – лишь одна из областей. ИИ может, например, и музыку создавать, но к этому я отношусь критичнее: музыка для меня – настоящее искусство. Программирование для меня скорее ремесло: хобби, страсть и вопрос умения. Поскольку именно этого умения мне не хватает, я взял себе в помощь Claude.",
