"Repetierbüchse im Kaliber .338: Ein Treffer in Kopf oder Torso, und das Duell ist entschieden. Langsam im Anschlag, gnadenlos im Ergebnis.":"Винтовка с продольно-скользящим затвором калибра .338: одно попадание в голову или торс – и дуэль решена. Медленная вскидка, беспощадный результат.",
"Repetierer":"Продольно-скользящий затвор",
"Repetierer der Weltkriegszeit mit Nussbaum-Vollschaft und Kimme und Korn: fünf Schuss, Kammer auf, Kammer zu. Ohne Optik verlangt er ein ruhiges Auge – trifft er, steht keiner mehr auf.":"Винтовка времён мировой войны с цельной ореховой ложей и открытым прицелом: пять патронов, затвор назад, затвор вперёд. Без оптики нужен твёрдый глаз – если попал, никто не встанет.",
"Repetiergewehr im Kaliber 7,62 × 51 mit schwerem, kanneliertem Lauf: leichter und schneller durchgeladen als der Brecher, ein Kopftreffer genügt auf jede Distanz, ein Torsotreffer auf mittlere.":"Винтовка с продольно-скользящим затвором калибра 7,62 × 51 с тяжёлым рифлёным стволом: легче и быстрее перезаряжается, чем «Брехер»; выстрел в голову убивает на любой дистанции, в торс – на средней.",
