"Ruhig. Nase leicht nach vorn, dann fliegt er von selbst. Die Landezone ist rot markiert.":"Спокойно. Нос чуть вперёд – и он полетит сам. Зона высадки отмечена красным.",
"Ruhig: Die Waffe bleibt vor Wänden in Haltung und wird über allem gezeichnet (wie in den meisten Shootern). Hochnehmen/An den Körper ziehen: nur, wenn wirklich etwas vor der Mündung steht. Keine Anpassung: Die Waffe ragt sichtbar in Wände. Schüsse starten immer am Auge.":"Спокойно: у стен оружие сохраняет положение и рисуется поверх всего (как в большинстве шутеров). Поднять/Прижать к телу: только если перед стволом что-то есть. Без коррекции: оружие заметно уходит в стены. Выстрел всегда идёт от глаза.",
