"Schwerer Rückstoß, ehrlicher Treffer: Das KV-47 schlägt mit jeder Kugel hart zu und verliert auch über lange Achsen kaum an Wucht. Wer die Mündung bändigt, gewinnt fast jedes Duell auf mittlere Distanz.":"Тяжёлая отдача, честное попадание: KV-47 бьёт мощно каждой пулей и почти не теряет силу на дальних линиях. Кто укротит ствол, выиграет почти любую дуэль на средней дистанции.",
"Schwerer Schaft":"Тяжёлый приклад",
"Schweres Maschinengewehr im Kaliber 12,7 mm, für den Einsatz aus der Hand umgebaut: Gurtkasten mit fünfzig Patronen, Zweibein, Tragegriff. Drei Treffer genügen, Deckung aus Holz, Blech und Ziegel hält nicht – dafür trägt man vierzehn Kilo und jeder Feuerstoß reißt die Mündung hoch.":"Крупнокалиберный пулемёт 12,7 мм, переделанный для стрельбы с рук: короб с лентой на пятьдесят патронов, сошки, ручка для переноски. Хватает трёх попаданий, укрытия из дерева, жести и кирпича не держат — зато весит четырнадцать килограммов, и каждая очередь задирает ствол.",
