"Sie glauben, Sie hätten gewonnen, Unteroffizier. Sie haben einen einzigen Mann verhaftet.":"Думаете, вы победили, сержант? Вы арестовали одного-единственного человека.",
"Sie haben Söldner bezahlt, damit sie eine Waffenruhe brechen. Damit Sie wieder liefern können. Das ist sehr wohl Ihre Sache.":"Вы платили наёмникам, чтобы сорвать перемирие. Чтобы снова поставлять. Это очень даже ваше дело.",
"Sie haben es getan, damit andere morgen nicht kämpfen müssen. Auch das wird man nicht vergessen.":"Они сделали это, чтобы другим не пришлось воевать завтра. И это тоже не забудут.",
"Sie haben gesagt, meiner Frau und den Kindern geschieht nichts, solange ich fahre und schweige.":"Они сказали, что с женой и детьми ничего не случится, пока я вожу груз и молчу.",
"Sie haben uns die Wahrheit aufbewahrt. Das ist mehr wert, als Sie denken.":"Вы сохранили для нас правду. Это стоит больше, чем вы думаете.",
"Sie haben uns gewarnt, Major. Warum?":"Вы нас предупредили, майор. Почему?",
"Sie haben uns! Feuer frei, aber schnell!":"Нас засекли! Огонь, но быстро!",
"Sie haben uns. Feuer frei – und dann weiter, bevor mehr kommen!":"Нас засекли. Огонь – и дальше, пока не подошли ещё!",
"Sie halten den Platz! Bleib an den Säulen, nicht über die offene Fläche!":"Они держат площадь! Держись у колонн, не выходи на открытое место!",
"Sie kamen über die Furt. Nicht alle. Emil hat den Namen jedes Einzelnen bis zu seinem letzten Tag gewusst.":"Они перешли брод. Не все. Эмиль помнил имя каждого до последнего дня.",
"Sie kommen auf die Kirche zu! Von Norden und Süden!":"Они идут к церкви! С севера и юга!",
"Sie kommen durch die Seitengänge! Und der Ostflügel brennt!":"Они идут боковыми проходами! И восточное крыло горит!",
"Sie kommen hinter dem Rauch hervor! Von Norden!":"Выходят из дыма! С севера!",
"Sie kommen in Wellen. Sie hören jeden Schuss.":"Они идут волнами. Они слышат каждый выстрел.",
"Sie kommen. Such dir eine Stellung und sichere die Zugänge.":"Они идут. Займите позицию и прикройте подходы.",
"Sie sind am Tor! Zurück in die Stellung!":"Они у ворот! Назад на позицию!",
"Sie sind an der Kirchentür! Falke!":"Они у дверей церкви! Фальке!",
"Sie sind drin. Gut so.":"Они внутри. Хорошо.",
"Sie sind in der Ruine! Falke, zurück zur Kapelle!":"Они в руинах! Фальке, назад к часовне!",
"Sie sind in der Ruine! Zurück in die Mauern!":"Они в руинах! Назад за стены!",
"Sie sitzen in der Ruine! Wir gehen links herum!":"Они в руинах! Обходим слева!",
"Sie verhaften einen Geschäftsmann, Feldwebel. Ich habe Ware geliefert. Was die Leute damit machen, ist nicht meine Sache.":"Вы арестовываете бизнесмена, старшина. Я поставлял товар. Что с ним делают люди – не моё дело.",
"Sie versuchen es noch einmal! Von Osten!":"Они снова пытаются! С востока!",
"Sie wollen zurück ins Haus! Haltet den Eingang!":"Они хотят вернуться в здание! Держите вход!",
"Sie wollen, dass es so aussieht, als hätten wir die Waffenruhe gebrochen.":"Они хотят, чтобы всё выглядело так, будто перемирие нарушили мы.",
