"Team-Deathmatch ohne Wiedereinstieg: Wer fällt, schaut bis zur nächsten Runde zu. Eine Runde gewinnt das Team, das als letztes noch steht. Wer zuerst drei von fünf Runden holt, gewinnt das Match.":"Командный бой без возрождения: павший наблюдает до следующего раунда. Раунд выигрывает команда, которая устоит последней. Кто первым возьмёт три раунда из пяти, побеждает в матче.",
