"Teleport: linken Stick nach vorn halten, Bogen auf den Boden richten, loslassen – kurzes Abblenden, keine Bewegung im Bild. Am angenehmsten bei Übelkeit.":"Телепорт: держите левый стик вперёд, наведите дугу на землю, отпустите – короткое затемнение, без движения в кадре. Удобнее всего при тошноте.",
"Teleport: {0}":"Телепорт: {0}",
"Teleskop-Schlagstock aus Stahl: zwei schnelle Schläge. Spezial „Betäuben“: jeder Treffer lässt den Gegner 1,5 s lang schwer vorankommen.":"Стальная телескопическая дубинка: два быстрых удара. Особое «Оглушение»: каждое попадание на 1,5 с сильно замедляет врага.",
"Tempo":"Скорость",
"Test beendet.":"Проверка окончена.",
"Teste jede Waffe in Ruhe: Klappziele auf verschiedenen Distanzen, unbegrenzte Reservemunition und eine Trefferstatistik, die nicht lügt. Rund um den Stand liegt das Übungsgelände: alle Panzer, Transporter, Autos, Hubschrauber und Jets zum Einsteigen, eine Fahrstrecke, die Panzerschießbahn bis 2500 m mit Trefferanzeige und ein Flugfeld mit Luft- und Bodenzielen – allein, ohne Gegner.":"Испытайте любое оружие спокойно: падающие мишени на разных дистанциях, бесконечный запас патронов и честная статистика попаданий. Вокруг стрельбища – учебный полигон: все танки, транспорт, машины, вертолёты и самолёты, трасса для вождения, танковое стрельбище до 2500 м с индикацией попаданий и аэродром с воздушными и наземными целями – в одиночку, без противников.",
"Testgelände":"Полигон",
"Testmatch – keine EP":"Тестовый матч – без опыта",
