"Tiefenschärfe beim Zielen":"Глубина резкости при прицеливании",
"Tiger":"Тигр",
"Tipp: Blutungen stillst du mit Verband oder Abbinden, bevor das Bild grau wird.":"Совет: останавливай кровотечение повязкой или жгутом, пока картинка не стала серой.",
"Tipp: Controller? Steuerkreuz wählt, A bestätigt, B geht zurück.":"Совет: геймпад? Крестовина – выбор, A – подтвердить, B – назад.",
"Tipp: Das Übungsgelände hat jedes Fahrzeug zum Einsteigen – ohne Gegner.":"Совет: на полигоне можно сесть в любую технику – без противников.",
"Tipp: Dauerfeuer frisst sich durch dünne Wände. Deckung ist nicht gleich Schutz.":"Совет: длинные очереди прошивают тонкие стены. Укрытие – не значит защита.",
"Tipp: Fünf Schuss auf den Punkt im Hauptmenü schießen die Waffe ein.":"Совет: пять выстрелов в точку в главном меню пристреливают оружие.",
"Tipp: Gehockt und still stehend streut jede Waffe am wenigsten.":"Совет: присев и стоя на месте, любое оружие даёт наименьший разброс.",
"Tipp: Grafik ruckelt? Unter Einstellungen eine Stufe niedriger wählen.":"Совет: картинка дёргается? Выберите в настройках уровень ниже.",
"Tipp: Halbleere Magazine bleiben in der Simulation halbleer. Zähl mit.":"Совет: в симуляции полупустые магазины остаются полупустыми. Считай патроны.",
"Tipp: Im Panzer sagt der Kommandant das Ziel an – Richtschütze, Panzer, halbrechts, 800, Feuer.":"Совет: в танке командир называет цель – наводчик, танк, правее, 800, огонь.",
"Tipp: Mit dem Raumcode spielen Browser, Handy, VR und PC-App zusammen.":"Совет: по коду комнаты вместе играют браузер, телефон, VR и приложение для ПК.",
