"Tippe auf {0} – je nach Browser in der Adressleiste oder im Menü {1}.":"Нажмите {0} – в зависимости от браузера в адресной строке или в меню {1}.",
"Tippe auf {0} – unten in der Leiste oder neben der Adresse; in neueren iOS-Versionen erst auf „…“ {1}.":"Нажмите {0} – внизу на панели или рядом с адресом; в новых версиях iOS сначала «…» {1}.",
