"Unbekanntes Bauwerk.":"Неизвестная постройка.",
"Unberührbar":"Неприкасаемый",
"Und Hauptmann Elias Brandt, Nordkorps. Die Waffenruhe gilt – für beide Seiten, ab sofort und ohne Ausnahme. Niemand schießt, der nicht muss.":"И капитан Элиас Брандт, Северный корпус. Перемирие действует – для обеих сторон, немедленно и без исключений. Никто не стреляет без нужды.",
"Und achtet auf die Trupps mit Panzerfäusten. Die kommen leise durchs hohe Gras.":"И следите за группами с гранатомётами. Они тихо идут через высокую траву.",
"Und auf dem Vorfeld wird ein Hubschrauber betankt. Zivil lackiert, aber mit Zusatztanks. Weit genug für jedes Land, das keine Fragen stellt.":"А на перроне заправляют вертолёт. Гражданская окраска, но с дополнительными баками. Хватит до любой страны, где не задают вопросов.",
"Und danke an dich fürs Spielen. Über dein Feedback freue ich mich.":"И спасибо тебе, что играешь. Буду рад твоему отзыву.",
"Und der Kapitän? Anselm Vogt. Sie halten ihn im Kaibüro fest. Seine Familie haben sie bedroht, damit er fährt.":"А капитан? Ансельм Фогт. Его держат в конторе на причале. Угрожали его семье, чтобы он вёл судно.",
"Und der dritte?":"А третий?",
"Und die Brigade von Major Daren hat Befehl, mitzumarschieren.":"А бригаде майора Дарена приказано идти вместе с ним.",
"Und diesmal kommen wir alle heim.":"И на этот раз мы все вернёмся домой.",
"Und niemand schießt, der nicht muss. Wir sind nicht wie Kessar.":"И никто не стреляет без нужды. Мы не такие, как Кессар.",
"Und schießt nicht in die Kirche. Da drin sitzen noch Leute aus der Stadt.":"И не стреляйте по церкви. Там ещё сидят горожане.",
"Und warum sollten wir Ihnen trauen?":"А с чего нам вам верить?",
"Und wenn es losgeht: Die Geiseln sitzen mitten zwischen ihnen. Jeder Schuss muss sitzen.":"И когда начнётся: заложники сидят прямо среди них. Каждый выстрел должен быть точным.",
"Und wenn sie wirklich unsere Uniformen tragen?":"А если они и правда в нашей форме?",
"Und wer sind die beiden Stimmen? Die eine bin ich. Die andere ist eine KI. NULLPUNKT ist nämlich auch ein kleines Experiment.":"А кто эти два голоса? Один – это я. Другой – ИИ. Ведь NULLPUNKT – это ещё и небольшой эксперимент.",
"Unentdeckt":"Не обнаружен",
"Unentdeckt über die Kaimauer (Entdeckungsanzeige, Alarm)":"Незаметно пройти по причалу (индикатор обнаружения, тревога)",
"Unentschieden":"Ничья",
"Ungültig.":"Недопустимо.",
"Ungültige Markierung.":"Недопустимая метка.",
"Universal-MG der Weltkriegszeit mit gelochtem Laufmantel und Gurttrommel: über tausend Schuss pro Minute, das Geräusch eines reißenden Tuchs. Wer ihn nicht festhält, schießt in den Himmel.":"Единый пулемёт времён мировой войны с перфорированным кожухом и ленточным барабаном: больше тысячи выстрелов в минуту, звук рвущейся ткани. Не удержишь – стреляешь в небо.",
"Unser Beobachtungsposten am Panzerwrack ist in der Nacht überrannt worden. Mit ihm das Artillerie-Funkgerät.":"Наш наблюдательный пост у подбитого танка ночью смяли. А с ним и артиллерийскую рацию.",
"Unser Turmantrieb muss in die Werkstatt. Aber in der Reserve steht noch der alte Auerochs. Der hat schon meinen Vater gefahren.":"Привод башни надо в мастерскую. Но в резерве ещё стоит старый «Auerochs». На нём ещё мой отец ездил.",
"Unsere Frauen sind im ersten Lkw? Dann gehen wir. Danke.":"Наши жёны в первом грузовике? Тогда идём. Спасибо.",
"Unsere Tickets gehen zur Neige.":"Наши очки подкреплений на исходе.",
