"Weniger Wackeln, Verzeichnung und Animationen. Folgt auch der Systemeinstellung.":"Меньше тряски, искажений и анимаций. Учитывает и системную настройку.",
"Wenn Vahl so pünktlich ist wie seine Sendungen: knapp drei Minuten.":"Если Валь так же пунктуален, как его передачи, – чуть меньше трёх минут.",
"Wenn das rausgeht, glauben Tausende, das Nordkorps hätte Darens Brigade überfallen. Dann schießen alle auf alle.":"Если это уйдёт в эфир, тысячи поверят, что Северный корпус напал на бригаду Дарена. И все начнут стрелять во всех.",
"Wenn die Originale verschwinden, steht Kessars Fälschung allein da. Dann glaubt jeder seine Geschichte.":"Если подлинники исчезнут, останется только подделка Кессара. Тогда все поверят его версии.",
"Wenn du im Raum gehst, geht deine Figur genauso mit (Stick zusätzlich). Aus: seitlicher Kopfversatz lehnt statt zu gehen.":"Когда вы ходите по комнате, персонаж идёт так же (плюс стик). Выкл.: боковой сдвиг головы даёт наклон, а не шаг.",
"Wenn „Geladen!“ gemeldet ist und der Richtschütze aufgefasst hat: Feuerbefehl.":"Когда доложено «Заряжено!» и наводчик взял цель: команда «Огонь».",
