"Wer fällt, kommt in der nächsten Pause zurück":"Павшие возвращаются в следующую передышку",
"Wer ist Kranich, Herr Seyfried? Ihr Name steht in Kessars Notizbuch. Aber nicht allein.":"Кто такой Кранич, господин Зайфрид? Ваше имя в блокноте Кессара. Но не только оно.",
