"Wie Bodycam: Gegner werden nirgends angezeigt, minimales HUD, deutlich mehr Schaden, langsame Heilung.":"Как бодикам: врагов нигде не видно, минимум интерфейса, гораздо больше урона, медленное лечение.",
"Wie Bodycam: Spielstil „Ultra-Realismus“, kein HUD, Zeitstempel, Bodycam-Linse, tiefe Waffenhaltung, mehr Kamerabewegung, freies Zielen (leicht). Bei Reiseübelkeit danach unter „Grafik“ die Kamerabewegung senken.":"Как бодикам: стиль «Ультрареализм», без интерфейса, отметка времени, объектив бодикама, низкое положение оружия, больше движения камеры, свободное прицеливание (слабое). Если укачивает, уменьшите движение камеры в разделе «Графика».",
"Wie Bodycam: gefühlt kein HUD, Trägheit und Waffengewicht, Kopftreffer tödlich, keine Heilung außer Verbänden, Teambeschuss an.":"Как бодикам: интерфейса почти нет, инерция и вес оружия, попадание в голову смертельно, лечение только бинтами, огонь по своим включён.",
"Wie Bodycam: kein Fadenkreuz, keine Munitions- und Lebensanzeige. Nur das Nötigste.":"Как бодикам: без прицела, патронов и здоровья. Только самое нужное.",
"Wie NULLPUNKT entstanden ist":"Как появился NULLPUNKT",
"Wie am Bildschirm":"Как на экране",
