"Wie eine Helmkamera: deutliches Fischauge, Rauschen, leichte Kompression.":"Как нашлемная камера: заметный рыбий глаз, шум, лёгкое сжатие.",
"Wie eine echte Aufnahme: Gehäuserand, Zeitstempel, tiefe Waffenhaltung, mehr Bildfehler.":"Как настоящая запись: рамка корпуса, отметка времени, низкое оружие, больше артефактов.",
"Wie gefällt dir NULLPUNKT insgesamt?":"Как вам NULLPUNKT в целом?",
"Wie hast du gespielt?":"Как вы играли?",
"Wie lange du insgesamt auf dieser Webseite warst (nur eine Zahl)":"Сколько всего вы провели на этом сайте (только число)",
"Wie lange gefallene Soldaten liegen bleiben. Zum Schutz der Bildrate gilt je Grafikstufe eine Obergrenze (Niedrig 24, Mittel 48, Hoch 96, Ultra 160) – darüber verschwinden die ältesten zuerst.":"Как долго лежат павшие солдаты. Ради частоты кадров у каждого уровня графики есть предел (Низкое 24, Среднее 48, Высокое 96, Ультра 160) – сверх него первыми исчезают старые.",
