"Wir bleiben dicht bei dir, Falke.":"Держимся рядом, Фальке.",
"Wir bleiben hier am Zaun. Drei Posten. Einer geht Streife zwischen Scheune und Tank. Leise, Falke.":"Мы остаёмся у забора. Трое часовых. Один ходит между сараем и баком. Тихо, Фальке.",
"Wir bluten aus":"Мы истекаем кровью",
"Wir brauchen ihn lebend. Vor einem Gericht – nicht als Märtyrer für seine Anhänger.":"Он нужен живым. Перед судом – а не мучеником для своих сторонников.",
"Wir dachten, niemand kommt. Das Feuer war schon am Sägewerk.":"Мы думали, никто не придёт. Огонь был уже у лесопилки.",
"Wir gehen durch die Marktgasse, dann übers Torhaus zum Brunnenplatz. Leise, solange es geht.":"Идём через Рыночную улочку, потом через надвратную башню к площади фонтана. Тихо, пока получается.",
"Wir gehen in die Flanke!":"Заходим во фланг!",
"Wir gehen mit der Infanterie durchs Dorf vor. Halte uns die Häuser vom Hals.":"Мы идём с пехотой через деревню. Прикрой нас от домов.",
"Wir gehen rein!":"Заходим!",
"Wir greifen {0}{1} an.":"Атакуем {0}{1}.",
"Wir greifen {p} an!":"Атакуем {p}!",
"Wir halten dir den Rücken frei! Finger weg vom roten Kabel – das hat Krell dir beigebracht!":"Мы прикроем! Красный провод не трогай – Крелль учил!",
"Wir halten {0}{1}.":"Держим {0}{1}.",
"Wir halten {p}!":"Держим {p}!",
"Wir hören euch! Kommt nach Süden, am Kai entlang – wir halten euch den Weg frei!":"Слышим вас! Идите на юг вдоль причала – мы держим путь!",
"Wir landen. Wir landen! Nicht schießen!":"Садимся. Садимся! Не стреляйте!",
"Wir markieren sie für die Pioniere. Kein Alarm – sonst jagen sie die Ladung hoch, bevor wir sie sichern.":"Помечаем их для сапёров. Без тревоги – иначе они взорвут груз, прежде чем мы его возьмём.",
"Wir müssen nicht siegen, Lenz. Wir müssen nur lange genug stehen, bis der letzte Lkw draußen ist.":"Нам не нужно побеждать, Ленц. Нужно продержаться, пока не уйдёт последний грузовик.",
"Wir sehen dich auf der Galerie. Leg an und halte die Wachen kurz im Visier – dann sind sie markiert.":"Видим тебя на галерее. Прицелься и подержи часовых в прицеле – они будут помечены.",
"Wir sind eine Handvoll gegen eine Brigade, Herr Hauptmann.":"Нас горстка против бригады, товарищ капитан.",
"Wir sind getroffen!":"Нас подбили!",
"Wir verhandeln nicht mehr in Zelten und Kasernen. Die Menschen sollen sehen, was beschlossen wird – und wer es beschließt.":"Мы больше не ведём переговоры в палатках и казармах. Люди должны видеть, что решается – и кто решает.",
"Wird auf diesem Gerät gespeichert.":"Сохраняется на этом устройстве.",
"Wird dir beim Spielen übel? Kamerabewegung und Waffenträgheit senken, Fischauge verringern, Sichtfeld erhöhen – oder die Vorlage „Bodycam · Komfort“. Ganz ohne HUD wie bei Bodycam: HUD → „Realismus“.":"Укачивает? Уменьшите движение камеры и инерцию оружия, ослабьте рыбий глаз, увеличьте поле зрения – или выберите шаблон «Бодикам · Комфорт». Совсем без интерфейса, как на бодикаме: Интерфейс → «Реализм».",
"Wird eingenommen":"Захват",
"Wird erkannt, ist aber keine offizielle Plattform. Ob es flüssig läuft, entscheidet der Browser des Geräts.":"Распознаётся, но официальной платформой не является. Плавность зависит от браузера устройства.",
