"Wucht":"Подкалиберный",
"Wucht auf jede Entfernung. Wer den Rückstoß beherrscht, braucht nichts anderes.":"Мощь на любой дистанции. Кто владеет отдачей, тому больше ничего не нужно.",
"Wucht/Panzergranate gegen Panzer, Spreng gegen Pak, Bunker und Infanterie, Kanister auf kurze Entfernung.":"Подкалиберный/бронебойный – по танкам, фугасный – по ПТО, дотам и пехоте, картечь – вблизи.",
"Wucht: Taumeln, halber Schaden im Bogen":"Мощь: оглушение, половина урона в дуге",
"Wuchtgeschoss":"Подкалиберный",
"Wurfnetz":"Метательная сеть",
"Wähle Panzer, Karte und deinen Platz. Die KI besetzt den Rest der Besatzung; Winkelspiegel, Optiken und Innenräume für jeden Platz.":"Выберите танк, карту и своё место. Остальной экипаж – ИИ; перископы, оптика и интерьер для каждого места.",
"Wähle „Im Browser öffnen“ bzw. „In Chrome öffnen“.":"Выберите «Открыть в браузере» или «Открыть в Chrome».",
"Wähle „In Safari öffnen“ bzw. „Im Browser öffnen“.":"Выберите «Открыть в Safari» или «Открыть в браузере».",
