"Wähle „Zum Home-Bildschirm“ {0} und tippe auf „Hinzufügen“. „Als Web-App öffnen“ bleibt eingeschaltet.":"Выберите «На экран «Домой»» {0} и нажмите «Добавить». «Открывать как веб-приложение» оставьте включённым.",
