"Xbox":"Xbox",
"Y-Achse umkehren":"Инвертировать ось Y",
"ZF":"СНП",
"ZIEL 2,3 m · ×100 m":"ЦЕЛЬ 2,3 м · ×100 м",
"ZMB":"ЗМБ",
"Zebra":"Зебра",
"Zehn Abschüsse, ohne zu sterben.":"Десять убийств без смерти.",
"Zehn Freunde gleichzeitig in einem Match, und alles hat gehalten: ein voller Erfolg. Danach ging es direkt weiter: Verletzungen mit Verband und Wiederbeleben, neue Nahkampfwaffen wie Axt und Schlagstock, Fassaden, die nach Explosionen herausbrechen, Autos, die sich verformen, Fenster zum Zerschießen, über 20 Waffenaufsätze und die Stellungskriegskarte Niemandsland mit Gräben, die man mit dem Spaten selbst tiefer graben kann.":"Десять друзей одновременно в одном матче – и всё выдержало: полный успех. Дальше без паузы: ранения с перевязкой и реанимацией, новое холодное оружие вроде топора и дубинки, фасады, обрушающиеся от взрывов, деформируемые машины, простреливаемые окна, более 20 обвесов и карта позиционной войны «Ничейная земля» с окопами, которые можно углублять лопатой.",
