"Zielfernrohr: rechte Maustaste. Markieren: Ziel im Visier halten, bis der Balken voll ist. Nicht auf Zivilisten schießen.":"Прицел: правая кнопка мыши. Метка: держите цель в прицеле, пока шкала не заполнится. Не стреляйте по мирным.",
