"von Anthropic. Lesen und verstehen kann ich Code, ihn selbst zu schreiben liegt mir aber nicht. Diesen Teil hat Claude übernommen und meine Vorstellungen Zeile für Zeile umgesetzt. Da in NULLPUNKT fast alles aus Code entsteht, gilt das auch für Modelle, Karten und Klänge: gebaut nach meinen Vorgaben und so lange nachgebessert, bis sie gepasst haben. Ergänzt wird das durch freie Texturen und Umgebungslicht von Poly Haven und ambientCG.":"от Anthropic. Читать и понимать код я умею, а вот писать его сам – не моё. Эту часть взял на себя Claude и строчка за строчкой воплотил мои идеи. Поскольку в NULLPUNKT почти всё создаётся кодом, это касается и моделей, карт и звуков: они сделаны по моим указаниям и дорабатывались, пока не стали такими, как надо. Дополняют их свободные текстуры и освещение окружения от Poly Haven и ambientCG.",
