"Überlebe Welle um Welle gegen Untote, die dem Lärm folgen und dich von allen Seiten einkreisen. Schlurfer kommen langsam, aber in Massen, Hetzer rennen, Hünen halten viel aus. Kopftreffer beenden es sofort, Treffer in die Beine bremsen sie. Zwischen den Wellen bleibt kurz Zeit für Munition und Sanität.":"Переживите волну за волной нежити, которая идёт на шум и окружает со всех сторон. Шатуны медленные, но их много, бегуны несутся, громилы очень живучи. Выстрел в голову убивает сразу, попадания по ногам замедляют. Между волнами есть короткая передышка для боеприпасов и перевязки.",
